const COMBINED_QUESTIONS = [{"id":"ml-1","sourceBank":"microsoft-learn","type":"single","question":"A dataset adheres to a fixed schema in which every record has the same columns, represented as rows and columns in tables. How is this data best described?","options":["Unstructured data","Structured data","Semi-structured data","Binary data"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Structured Data","sub":null,"explanation":"Structured data adheres to a fixed schema so all data has the same fields. Most commonly the schema is tabular — rows representing each instance of an entity and columns representing its attributes — and is often stored in a relational database.","source":{"title":"Explore core data concepts: Identify data formats (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"ml-2","sourceBank":"microsoft-learn","type":"single","question":"Customer records are stored as JSON documents where most customers have an email address, some have several, and a few have none. Which type of data is this?","options":["Structured data","Semi-structured data","Unstructured data","Relational data"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Semi-structured Data","sub":null,"explanation":"Semi-structured data has some structure but allows variation between entity instances. JSON (JavaScript Object Notation) is a common format for semi-structured data, where the specific fields can vary from one record to another.","source":{"title":"Explore core data concepts: Identify data formats (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"ml-3","sourceBank":"microsoft-learn","type":"single","question":"Which of the following is an example of unstructured data?","options":["A table of customers with fixed columns","A set of JSON documents with varying fields","Documents, images, audio, and video files","A CSV file with a header row"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Unstructured Data","sub":null,"explanation":"Unstructured data has no specific structure. Documents, images, audio, video, and binary files are examples — they don't fit a tabular or even a semi-structured schema.","source":{"title":"Explore core data concepts: Identify data formats (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"ml-4","sourceBank":"microsoft-learn","type":"single","question":"Which file format stores structured data as plain text with fields separated by commas and is good for data that must be read by a wide range of applications in a human-readable form?","options":["Parquet","Avro","CSV (comma-separated values)","BLOB"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Delimited Text & JSON","sub":null,"explanation":"Comma-separated values (CSV) is the most common delimited text format — fields separated by commas, rows terminated by a new line. Delimited text is a good choice for structured data that needs to be accessed by many applications in a human-readable format.","source":{"title":"Explore core data concepts: Explore file storage (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/3-file-storage"}},{"id":"ml-5","sourceBank":"microsoft-learn","type":"single","question":"Which file format is a columnar format that is the de facto standard for modern data lakehouses and supports efficient compression and encoding?","options":["CSV","XML","Parquet","JSON"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Optimized File Formats","sub":null,"explanation":"Parquet is a columnar data format optimized for storage and processing — the de facto standard for modern data lakehouses. Data for each column is stored together in row groups, with metadata that helps locate data quickly. Avro, by contrast, is a row-based format.","source":{"title":"Explore core data concepts: Explore file storage (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/3-file-storage"}},{"id":"ml-6","sourceBank":"microsoft-learn","type":"single","question":"A database stores each record as a unique key with an associated value that can be in any format. Which type of non-relational (NoSQL) database is this?","options":["Document database","Key-value database","Graph database","Column family database"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Non-relational Database Types","sub":null,"explanation":"A key-value database stores each record as a unique key with an associated value in any format. A document database is a specific form of key-value store where the value is a JSON document; graph databases store nodes and relationships; column family databases group columns into families.","source":{"title":"Explore core data concepts: Explore databases (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/4-databases"}},{"id":"ml-7","sourceBank":"microsoft-learn","type":"single","question":"Which type of non-relational database stores entities as nodes with links that define the relationships between them?","options":["Key-value database","Document database","Column family database","Graph database"],"correct":[3],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Graph Databases","sub":null,"explanation":"A graph database stores entities as nodes with links (edges) to define relationships between them. This is useful when the connections between data are as important as the data itself.","source":{"title":"Explore core data concepts: Explore databases (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/4-databases"}},{"id":"ml-8","sourceBank":"microsoft-learn","type":"single","question":"A system records many small, discrete units of work such as payments, optimizing storage for fast create, retrieve, update, and delete (CRUD) operations. What is this type of processing called?","options":["Online Analytical Processing (OLAP)","Online Transactional Processing (OLTP)","Batch processing","Stream processing"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1C","topic":"Transactional Workloads (OLTP)","sub":null,"explanation":"Transactional systems record transactions (small discrete units of work) and are often high-volume. This work is referred to as Online Transactional Processing (OLTP); storage is optimized for both reads and writes to support CRUD operations.","source":{"title":"Explore core data concepts: Transactional data processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/5-transactional-data-processing"}},{"id":"ml-9","sourceBank":"microsoft-learn","type":"single","question":"In the ACID properties of a transaction, which property ensures that a transaction is treated as a single unit that either succeeds completely or fails completely?","options":["Consistency","Isolation","Atomicity","Durability"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1C","topic":"ACID Semantics","sub":null,"explanation":"Atomicity means each transaction is treated as a single unit that succeeds completely or fails completely — e.g., a funds transfer must both debit one account and credit the other, or neither.","source":{"title":"Explore core data concepts: Transactional data processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/5-transactional-data-processing"}},{"id":"ml-10","sourceBank":"microsoft-learn","type":"single","question":"Which statement best describes an analytical data processing workload?","options":["It is optimized for high-volume read/write of individual records in real time","It typically uses read-only (or read-mostly) systems storing large volumes of historical data for reporting and analysis","It only processes streaming data as it arrives","It stores each record as a key-value pair"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1C","topic":"Analytical Workloads (OLAP)","sub":null,"explanation":"Analytical data processing typically uses read-only or read-mostly systems that store vast volumes of historical data or business metrics, supporting reporting, visualization, and analysis — often through data warehouses, data lakes, and OLAP/semantic models.","source":{"title":"Explore core data concepts: Analytical data processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/6-analytical-processing"}},{"id":"ml-11","sourceBank":"microsoft-learn","type":"single","question":"In an analytics pipeline, data is copied into the analytical store first and transformed afterward. Which pattern is this?","options":["ETL (extract, transform, load)","ELT (extract, load, transform)","OLTP","CRUD"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1C","topic":"ETL vs ELT","sub":null,"explanation":"In ELT (extract, load, transform), data is copied to the store and then transformed — a pattern common in modern lakehouses. In ETL the data is transformed before being loaded into the analytical store.","source":{"title":"Explore core data concepts: Analytical data processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/6-analytical-processing"}},{"id":"ml-12","sourceBank":"microsoft-learn","type":"single","question":"Which data professional is responsible for the design, implementation, and operation of databases — including backup/recovery plans, performance, and managing security by granting or denying access?","options":["Data analyst","Data engineer","Database administrator","Data scientist"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1D","topic":"Database Administrator","sub":null,"explanation":"A database administrator manages databases — overall availability, performance, and optimization — and is responsible for backup and recovery plans and for managing data security by granting or denying access to users.","source":{"title":"Explore data roles and services: Explore job roles (Training)","url":"https://learn.microsoft.com/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"ml-13","sourceBank":"microsoft-learn","type":"single","question":"Which role manages infrastructure and processes for data integration — building pipelines to ingest, cleanse, and transform data between systems, and ensuring data privacy?","options":["Database administrator","Data engineer","Data analyst","Business user"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1D","topic":"Data Engineer","sub":null,"explanation":"A data engineer designs and implements data-related workloads including ingestion pipelines and cleansing/transformation activities across relational and non-relational stores, and owns the management and monitoring of data pipelines.","source":{"title":"Explore data roles and services: Explore job roles (Training)","url":"https://learn.microsoft.com/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"ml-14","sourceBank":"microsoft-learn","type":"single","question":"Which role explores and analyzes data to identify trends, builds analytical models, and creates reports and visualizations so a business can make informed decisions?","options":["Data engineer","Database administrator","Data analyst","Solution architect"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1D","topic":"Data Analyst","sub":null,"explanation":"A data analyst enables businesses to maximize the value of their data by exploring data to identify trends and relationships, designing analytical models, and delivering insights through reports and visualizations.","source":{"title":"Explore data roles and services: Explore job roles (Training)","url":"https://learn.microsoft.com/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"ml-15","sourceBank":"microsoft-learn","type":"single","question":"In a relational database, what uniquely identifies each row (instance of an entity) in a table and can be referenced by other tables?","options":["A foreign key only","A primary key","An index","A view"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Relational Data Features","sub":null,"explanation":"Each instance of an entity is assigned a primary key that uniquely identifies it, and these keys are used to reference the entity in other tables (as foreign keys). Relational tables store structured data where each row has the same columns.","source":{"title":"Explore relational data: Understand relational data (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/2-understand-relational-data"}},{"id":"ml-16","sourceBank":"microsoft-learn","type":"single","question":"What is the main purpose of normalization in a relational database?","options":["To duplicate data across tables for faster reads","To eliminate duplicate data values so that, for example, a customer's details are stored only once","To convert tables into JSON documents","To encrypt the data at rest"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Normalization","sub":null,"explanation":"Normalization in part means the elimination of duplicate data values, so that (for example) the details of an individual customer are stored only once rather than for each sales order they place. Keys are used to reference data across tables.","source":{"title":"Explore core data concepts: Explore databases (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/4-databases"}},{"id":"ml-17","sourceBank":"microsoft-learn","type":"single","question":"You need to create and modify tables and other database objects. Which group of SQL statements do you use?","options":["Data Manipulation Language (DML)","Data Control Language (DCL)","Data Definition Language (DDL)","Transact-SQL only"],"correct":[2],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"SQL Statement Groups (DDL/DCL/DML)","sub":null,"explanation":"DDL (Data Definition Language) statements — such as CREATE, ALTER, DROP, and RENAME — are used to create, modify, and remove tables and other objects. DML manipulates rows; DCL manages permissions.","source":{"title":"Explore relational data: Explore SQL (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/4-query-with-sql"}},{"id":"ml-18","sourceBank":"microsoft-learn","type":"single","question":"Which SQL statement is used to read (retrieve) rows from a table?","options":["INSERT","SELECT","GRANT","CREATE"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"DML Statements","sub":null,"explanation":"SELECT is the DML statement used to read rows from a table. INSERT adds rows, UPDATE modifies rows, and DELETE removes rows; GRANT is a DCL statement and CREATE is a DDL statement.","source":{"title":"Explore relational data: Explore SQL (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/4-query-with-sql"}},{"id":"ml-19","sourceBank":"microsoft-learn","type":"single","question":"Which SQL dialect is used by Microsoft SQL Server, Azure SQL Database, and Azure SQL Managed Instance?","options":["PL/SQL","pgSQL","Transact-SQL (T-SQL)","MQL"],"correct":[2],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"SQL Dialects","sub":null,"explanation":"Transact-SQL (T-SQL) is the dialect used by Microsoft SQL Server and the Azure SQL services based on the SQL Server engine. PL/SQL is Oracle's dialect and pgSQL is PostgreSQL's.","source":{"title":"Explore relational data: Explore SQL (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/4-query-with-sql"}},{"id":"ml-20","sourceBank":"microsoft-learn","type":"single","question":"What is a view in a relational database?","options":["A physical copy of a table stored on disk","A virtual table based on the results of a SELECT query","A stored set of SQL statements that run on command","A sorted copy of a column used to speed up searches"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Database Objects — Views","sub":null,"explanation":"A view is a virtual table based on the results of a SELECT query — a window onto rows in one or more underlying tables. A stored procedure encapsulates SQL that runs on command; an index speeds up searches.","source":{"title":"Explore relational data: Describe database objects (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/5-database-objects"}},{"id":"ml-21","sourceBank":"microsoft-learn","type":"single","question":"Which database object helps the database engine find rows faster by keeping a sorted copy of one or more columns with pointers to the corresponding rows?","options":["A view","A stored procedure","An index","A trigger"],"correct":[2],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Database Objects — Index","sub":null,"explanation":"An index keeps a sorted copy of a column with pointers to the matching rows, like the index at the back of a book — letting the query optimizer fetch data faster than scanning the whole table. Indexes consume storage and add overhead to writes.","source":{"title":"Explore relational data: Describe database objects (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/5-database-objects"}},{"id":"ml-22","sourceBank":"microsoft-learn","type":"single","question":"A team wants full administrative control over the operating system and the SQL Server instance for a lift-and-shift migration. Which Azure SQL option should they choose?","options":["Azure SQL Database (single database)","Azure SQL Managed Instance","SQL Server on Azure Virtual Machines","Azure SQL Database elastic pool"],"correct":[2],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Azure SQL — IaaS vs PaaS","sub":null,"explanation":"SQL Server on Azure Virtual Machines is the IaaS option — it gives full control over the OS and SQL Server engine and is best for migrations and applications that require OS-level access. SQL Database and Managed Instance are PaaS and don't expose the OS.","source":{"title":"What is Azure SQL? (IaaS vs PaaS)","url":"https://learn.microsoft.com/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"ml-23","sourceBank":"microsoft-learn","type":"single","question":"Which Azure SQL option is a PaaS service offering near 100% compatibility with the SQL Server engine, designed for migrating many on-premises databases with minimal changes?","options":["Azure SQL Database","Azure SQL Managed Instance","SQL Server on Azure VMs","Azure Database for PostgreSQL"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Azure SQL Managed Instance","sub":null,"explanation":"Azure SQL Managed Instance is a PaaS service with near 100% compatibility with the latest SQL Server engine and native VNet support — best for lift-and-shift migrations of many databases with minimal changes while still getting PaaS benefits like automated patching and backups.","source":{"title":"What is Azure SQL Managed Instance?","url":"https://learn.microsoft.com/azure/azure-sql/managed-instance/sql-managed-instance-paas-overview"}},{"id":"ml-24","sourceBank":"microsoft-learn","type":"single","question":"Which Azure SQL deployment is a fully managed PaaS option optimized for modern cloud-born applications, available as a single database or an elastic pool?","options":["SQL Server on Azure VMs","Azure SQL Database","Azure Database for MySQL","Azure Cosmos DB"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Azure SQL Database","sub":null,"explanation":"Azure SQL Database is a fully managed PaaS option optimized for modern cloud applications, offered as a single database (its own resources via a logical server) or an elastic pool (databases sharing resources). It minimizes administration — no OS or engine to manage.","source":{"title":"What is Azure SQL? (service comparison)","url":"https://learn.microsoft.com/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"ml-25","sourceBank":"microsoft-learn","type":"single","question":"An organization runs an existing PostgreSQL application and wants a fully managed Azure service for it without managing servers. Which service fits?","options":["Azure Database for PostgreSQL","Azure SQL Managed Instance","Azure Cosmos DB for Table","SQL Server on Azure VMs"],"correct":[0],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"Open-source Database Services","sub":null,"explanation":"Azure provides managed services for popular open-source database engines — Azure Database for PostgreSQL and Azure Database for MySQL — so you can run those open-source systems as fully managed PaaS offerings without managing the underlying infrastructure.","source":{"title":"Azure Database for PostgreSQL overview","url":"https://learn.microsoft.com/azure/postgresql/flexible-server/service-overview"}},{"id":"ml-26","sourceBank":"microsoft-learn","type":"single","question":"Which Azure Storage service is designed to store massive amounts of unstructured data as binary large objects, organized in containers?","options":["Azure Files","Azure Table storage","Azure Blob storage","Azure Cosmos DB"],"correct":[2],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Azure Blob Storage","sub":null,"explanation":"Azure Blob Storage stores massive amounts of unstructured data as blobs (binary large objects). Blobs live in containers within a storage account, and access is controlled at the container level.","source":{"title":"Explore Azure Storage: Azure blob storage (Training)","url":"https://learn.microsoft.com/training/modules/explore-provision-deploy-non-relational-data-services-azure/2-azure-blob-storage"}},{"id":"ml-27","sourceBank":"microsoft-learn","type":"single","question":"Which Azure Blob Storage access tier offers the lowest storage cost but stores data offline, so retrieval can take hours while the blob is rehydrated?","options":["Hot tier","Cool tier","Cold tier","Archive tier"],"correct":[3],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Blob Access Tiers","sub":null,"explanation":"The Archive tier provides the lowest storage cost but the highest latency — blobs are stored offline and must be rehydrated (changed to Hot, Cool, or Cold) before reading, which can take hours. Hot/Cool/Cold tiers have millisecond read latency.","source":{"title":"Explore Azure Storage: Azure blob storage (Training)","url":"https://learn.microsoft.com/training/modules/explore-provision-deploy-non-relational-data-services-azure/2-azure-blob-storage"}},{"id":"ml-28","sourceBank":"microsoft-learn","type":"single","question":"Which Azure Storage redundancy option asynchronously replicates your data to a secondary region hundreds of miles away to protect against a regional disaster?","options":["Locally redundant storage (LRS)","Zone-redundant storage (ZRS)","Geo-redundant storage (GRS)","Block blob storage"],"correct":[2],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Storage Redundancy","sub":null,"explanation":"Geo-redundant storage (GRS) — and geo-zone-redundant storage (GZRS) — asynchronously replicate data to a secondary region for protection against regional disasters. LRS keeps three copies in one datacenter; ZRS spreads copies across zones in the primary region.","source":{"title":"Explore Azure Storage: Azure blob storage (Training)","url":"https://learn.microsoft.com/training/modules/explore-provision-deploy-non-relational-data-services-azure/2-azure-blob-storage"}},{"id":"ml-29","sourceBank":"microsoft-learn","type":"single","question":"Which Azure Storage service provides cloud-based network file shares accessible over the SMB and NFS protocols?","options":["Azure Blob storage","Azure Files","Azure Table storage","Azure Cosmos DB"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Azure Files","sub":null,"explanation":"Azure Files provides cloud-based network shares (like on-premises file shares) that can be mounted by multiple users and applications. It supports the Server Message Block (SMB) and Network File System (NFS) protocols.","source":{"title":"Explore Azure Storage: Azure Files (Training)","url":"https://learn.microsoft.com/training/modules/explore-provision-deploy-non-relational-data-services-azure/4-azure-files"}},{"id":"ml-30","sourceBank":"microsoft-learn","type":"single","question":"In Azure Table storage, which combination uniquely identifies a row and is used to group and quickly locate related rows?","options":["Primary key and foreign key","PartitionKey and RowKey","ContainerKey and BlobKey","DatabaseKey and TableKey"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Azure Table Storage","sub":null,"explanation":"Azure Table storage is a NoSQL key/value store. Each row's key has two parts: a PartitionKey (groups related rows into a partition) and a RowKey (unique within the partition). Including the partition key in a query narrows the data scanned and improves performance.","source":{"title":"Explore Azure Storage: Azure Tables (Training)","url":"https://learn.microsoft.com/training/modules/explore-provision-deploy-non-relational-data-services-azure/5-azure-tables"}},{"id":"ml-31","sourceBank":"microsoft-learn","type":"single","question":"Which scenario is the best fit for Azure Cosmos DB?","options":["An application needing complex multi-table joins over highly structured relational data","A globally distributed IoT or gaming app needing flexible schema and single-digit millisecond latency","Large-scale historical data warehousing for BI reporting","Storing network file shares for office documents"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Azure Cosmos DB Use Cases","sub":null,"explanation":"Cosmos DB is a strong fit for apps needing flexible schema, global reach, and consistent low latency — IoT/telemetry, gaming, retail/e-commerce, and web/mobile apps. For complex multi-table joins use Azure SQL Database; for large-scale historical analytics use Fabric or Synapse.","source":{"title":"Explore Cosmos DB: Describe Azure Cosmos DB (Training)","url":"https://learn.microsoft.com/training/modules/explore-non-relational-data-stores-azure/2-describe-azure-cosmos-db"}},{"id":"ml-32","sourceBank":"microsoft-learn","type":"single","question":"Which statement about Azure Cosmos DB is correct?","options":["It is an on-premises-only relational database","It is a fully managed (PaaS) NoSQL database that is globally distributed and schema-agnostic","It requires you to define a fixed schema before storing data","It can only be deployed in a single Azure region"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Cosmos DB Characteristics","sub":null,"explanation":"Cosmos DB is a fully managed (PaaS) NoSQL database service that is schema-agnostic (items in a container can have different structures) and built for global distribution — you can add regions and Cosmos DB replicates data automatically for low-latency access.","source":{"title":"Explore Cosmos DB: Describe Azure Cosmos DB (Training)","url":"https://learn.microsoft.com/training/modules/explore-non-relational-data-stores-azure/2-describe-azure-cosmos-db"}},{"id":"ml-33","sourceBank":"microsoft-learn","type":"single","question":"Which Azure Cosmos DB API is the native API, stores data as JSON documents, supports a SQL-like query syntax, and is recommended for new applications?","options":["API for MongoDB","API for Apache Cassandra","API for NoSQL","API for Apache Gremlin"],"correct":[2],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Cosmos DB APIs — NoSQL","sub":null,"explanation":"The API for NoSQL is the native Cosmos DB API. It stores data as JSON documents, supports a SQL-like query syntax, and is recommended for new applications. (It was previously called the SQL API.)","source":{"title":"Explore Cosmos DB: Identify Cosmos DB APIs (Training)","url":"https://learn.microsoft.com/training/modules/explore-non-relational-data-stores-azure/3-cosmos-db-apis"}},{"id":"ml-34","sourceBank":"microsoft-learn","type":"single","question":"Your data is a network of entities and relationships (a social network). Which Azure Cosmos DB API is designed for graph data using vertices and edges?","options":["API for Table","API for Apache Gremlin","API for MongoDB","API for NoSQL"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Cosmos DB APIs — Gremlin","sub":null,"explanation":"The API for Apache Gremlin is designed for graph data, where entities are vertices (nodes) and relationships are edges. It suits scenarios like social networks, recommendation engines, and fraud detection.","source":{"title":"Explore Cosmos DB: Identify Cosmos DB APIs (Training)","url":"https://learn.microsoft.com/training/modules/explore-non-relational-data-stores-azure/3-cosmos-db-apis"}},{"id":"ml-35","sourceBank":"microsoft-learn","type":"single","question":"Which Azure/Fabric service is used to build pipelines that orchestrate multi-step data movement and transformation for ingesting data into an analytical store?","options":["Power BI Desktop","Fabric Data Factory / Azure Data Factory","Azure Blob storage","Azure Table storage"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Data Ingestion Pipelines","sub":null,"explanation":"Fabric Data Factory (and standalone Azure Data Factory) builds pipelines made up of activities that move and transform data, using linked services to connect to sources and destinations. It's the recommended starting point for pipeline-based ingestion.","source":{"title":"Large-scale analytics: Data ingestion pipelines (Training)","url":"https://learn.microsoft.com/training/modules/examine-components-of-modern-data-warehouse/3-data-ingestion-pipelines"}},{"id":"ml-36","sourceBank":"microsoft-learn","type":"single","question":"In a relational data warehouse, numeric values are stored in central tables related to tables that represent the entities by which data is aggregated. What are these two table types called?","options":["Block tables and page tables","Fact tables and dimension tables","Partition tables and row tables","Bronze tables and gold tables"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Data Warehouse — Star Schema","sub":null,"explanation":"A data warehouse commonly uses a star schema: numeric measures are stored in central fact tables related to dimension tables (e.g., customer, product, store, time) by which the data can be aggregated. Extending dimensions into further tables creates a snowflake schema.","source":{"title":"Large-scale analytics: Analytical data stores (Training)","url":"https://learn.microsoft.com/training/modules/examine-components-of-modern-data-warehouse/4-analytical-data-stores"}},{"id":"ml-37","sourceBank":"microsoft-learn","type":"single","question":"Which analytical store combines the flexible file storage of a data lake with the relational SQL querying semantics of a data warehouse, enabled by Delta Lake?","options":["A data lakehouse","A key-value store","An OLTP database","A blob container"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Data Lake vs Lakehouse","sub":null,"explanation":"A data lakehouse is a hybrid approach: raw data is stored as files in a data lake, and a SQL analytics endpoint exposes those files as queryable tables. It's enabled by Delta Lake, which adds relational/transactional capabilities on top of Parquet files.","source":{"title":"Large-scale analytics: Analytical data stores (Training)","url":"https://learn.microsoft.com/training/modules/examine-components-of-modern-data-warehouse/4-analytical-data-stores"}},{"id":"ml-38","sourceBank":"microsoft-learn","type":"single","question":"Which Microsoft service is a unified SaaS analytics platform whose workloads all share a single tenant-wide data lake called OneLake?","options":["Azure Databricks","Microsoft Fabric","Azure Cosmos DB","Azure Files"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Microsoft Fabric","sub":null,"explanation":"Microsoft Fabric is a unified SaaS analytics platform that brings storage, data engineering, data warehousing, and reporting into a single workspace, all backed by OneLake — a tenant-wide data lake shared across every Fabric workload, using Delta Lake as the standard format.","source":{"title":"Large-scale analytics: Data warehousing architecture (Training)","url":"https://learn.microsoft.com/training/modules/examine-components-of-modern-data-warehouse/2-describe-warehousing"}},{"id":"ml-39","sourceBank":"microsoft-learn","type":"single","question":"Which Microsoft cloud analytics platform is built on Apache Spark and optimized for large-scale data engineering, data science, and SQL analytics, using Delta Lake as its native storage format?","options":["Microsoft Fabric","Azure Databricks","Power BI","Azure Table storage"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"Azure Databricks","sub":null,"explanation":"Azure Databricks is a cloud analytics platform built on Apache Spark, optimized for large-scale data engineering, data science, and SQL analytics. It runs inside your Azure subscription and uses Delta Lake as its native open storage format.","source":{"title":"Large-scale analytics: Data warehousing architecture (Training)","url":"https://learn.microsoft.com/training/modules/examine-components-of-modern-data-warehouse/2-describe-warehousing"}},{"id":"ml-40","sourceBank":"microsoft-learn","type":"single","question":"Which characteristic best describes batch processing?","options":["Each event is processed individually the moment it arrives","Data is collected and stored, then the whole group is processed together, often on a schedule","It always has latency measured in milliseconds","It can only access the most recent data within a rolling time window"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"Batch Processing","sub":null,"explanation":"In batch processing, newly arriving data is collected and stored, and the whole group is processed together as a batch — often on a schedule or when a volume threshold is reached. Latency is typically hours, and it can process the full dataset.","source":{"title":"Real-time analytics: Batch and stream processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-stream-processing/2-batch-stream"}},{"id":"ml-41","sourceBank":"microsoft-learn","type":"single","question":"Which statement is true of stream processing compared with batch processing?","options":["It waits for all data to be collected before processing","It processes each new piece of data in real time as it arrives, typically with latency of seconds or milliseconds","It is only suitable for complex analytics over the full dataset","It always has latency of several hours"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"Stream Processing","sub":null,"explanation":"In stream processing, each new piece of data is processed in real time as it arrives, with latency in the order of seconds or milliseconds. It typically works on the most recent data or a rolling time window, ideal for time-critical operations.","source":{"title":"Real-time analytics: Batch and stream processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-stream-processing/2-batch-stream"}},{"id":"ml-42","sourceBank":"microsoft-learn","type":"single","question":"Which Azure service is commonly used as an ingestion source that manages a queue of event data, ensuring each event is processed in order and exactly once?","options":["Azure Event Hubs","Power BI Desktop","Azure Files","Azure SQL Database"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"Real-time Analytics Services","sub":null,"explanation":"Azure Event Hubs is a data ingestion service used to manage queues of event data so each event is processed in order, exactly once. Azure IoT Hub is similar but optimized for IoT devices; Apache Kafka is an open-source alternative.","source":{"title":"Real-time analytics: Common elements of stream processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-stream-processing/3-explore-common-elements"}},{"id":"ml-43","sourceBank":"microsoft-learn","type":"single","question":"Which Microsoft Fabric capability is an integrated toolset for real-time data, including Eventstreams and an Eventhouse queried with KQL?","options":["Power BI Desktop","Microsoft Fabric Real-Time Intelligence","Azure Data Lake Storage Gen2","Azure SQL Managed Instance"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"Fabric Real-Time Intelligence","sub":null,"explanation":"Microsoft Fabric Real-Time Intelligence is a complete toolset for real-time data, including Eventstreams (ingest/route/transform streams), Eventhouse (a store optimized for time-series/event data queried with KQL), Real-Time Dashboards, and Activator.","source":{"title":"Real-time analytics: Common elements of stream processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-stream-processing/3-explore-common-elements"}},{"id":"ml-44","sourceBank":"microsoft-learn","type":"single","question":"In a typical Power BI workflow, where do you import data, build the data model, and create reports before publishing them for business users to consume?","options":["The Power BI phone app","Power BI Desktop","Azure Data Factory","Azure Cosmos DB"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4C","topic":"Power BI Tools & Workflow","sub":null,"explanation":"A typical Power BI workflow starts in Power BI Desktop, where you import data from many sources, build an analytics data model, and create reports with interactive visualizations. You then publish to the Power BI service for business users to consume.","source":{"title":"Data visualization: Power BI tools and workflow (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-data-visualization/2-power-bi"}},{"id":"ml-45","sourceBank":"microsoft-learn","type":"single","question":"In a Power BI semantic (analytical) model, what are the numeric values you want to analyze, and the entities you aggregate them by, respectively called?","options":["Measures and dimensions","Rows and columns","Blobs and containers","Keys and indexes"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4C","topic":"Power BI Data Models","sub":null,"explanation":"An analytical/semantic model defines measures (the numeric values to analyze, stored in fact tables) and dimensions (the entities to aggregate by, stored in dimension tables). A fact table related to dimension tables forms a star schema.","source":{"title":"Data visualization: Core concepts of data modeling (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-data-visualization/3-data-modeling"}},{"id":"ml-46","sourceBank":"microsoft-learn","type":"single","question":"You want to examine a trend in revenue over time. Which Power BI visualization is most appropriate?","options":["Pie chart","Line chart","Map","Table"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4C","topic":"Choosing Visualizations","sub":null,"explanation":"Line charts are useful when you need to examine trends, often over time. Bar/column charts compare values across discrete categories; pie charts show proportions of a total; maps compare values across geographic areas.","source":{"title":"Data visualization: Considerations for data visualization (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-data-visualization/4-data-visualizations"}},{"id":"ml-47","sourceBank":"microsoft-learn","type":"single","question":"Which visualization is most appropriate for comparing categorized values as proportions of a total?","options":["Scatter plot","Line chart","Pie chart","Map"],"correct":[2],"skill":4,"confidence":"high","set":null,"section":"4C","topic":"Choosing Visualizations — Proportions","sub":null,"explanation":"Pie charts are often used to compare categorized values as proportions of a total. Scatter plots compare two numeric measures to find relationships; line charts show trends; maps compare values by location.","source":{"title":"Data visualization: Considerations for data visualization (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-data-visualization/4-data-visualizations"}},{"id":"ml-48","sourceBank":"microsoft-learn","type":"single","question":"In Microsoft Fabric, which feature creates a live reference to external storage so the data appears in your Lakehouse without copying or moving it?","options":["A OneLake shortcut","A batch pipeline copy activity","An Archive tier blob","A stored procedure"],"correct":[0],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"OneLake Shortcuts & Mirroring","sub":null,"explanation":"A OneLake shortcut is a live reference to external storage (ADLS Gen2, Amazon S3, Google Cloud Storage, or another OneLake location) that makes external data appear in your Lakehouse with no copying or movement — useful when data must stay in place for compliance or cost reasons.","source":{"title":"Large-scale analytics: Data ingestion pipelines (Training)","url":"https://learn.microsoft.com/training/modules/examine-components-of-modern-data-warehouse/3-data-ingestion-pipelines"}},{"id":"ml-101","sourceBank":"microsoft-learn","type":"single","question":"In data terms, what does an 'entity' typically represent and what are its 'attributes'?","options":["A file format; its compression settings","Something important to an organization (e.g., a customer); its characteristics (e.g., name, address)","A database server; its CPU and memory","A SQL statement; its parameters"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1A","topic":"Data Entities and Attributes","sub":null,"explanation":"Data structures often represent entities important to an organization (such as customers, products, or sales orders), and each entity typically has one or more attributes — characteristics like a customer's name, address, or phone number.","source":{"title":"Explore core data concepts: Identify data formats (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"ml-102","sourceBank":"microsoft-learn","type":"single","question":"Which open-source storage format builds on Parquet by adding a transaction log to enable ACID transactions, data versioning, and reliable updates on files in a data lake?","options":["CSV","Avro","Delta Lake","XML"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Delta Lake Format","sub":null,"explanation":"Delta Lake is an open-source storage format that builds on Parquet by adding a transaction log, which enables ACID transactions, data versioning, and reliable updates on top of files stored in a data lake.","source":{"title":"Explore core data concepts: Explore file storage (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/3-file-storage"}},{"id":"ml-103","sourceBank":"microsoft-learn","type":"single","question":"Which statement about relational and non-relational databases is correct?","options":["Relational databases store structured data in tables using keys; non-relational (NoSQL) databases don't apply a relational schema","Non-relational databases always enforce a fixed schema","Relational databases cannot use SQL","Document databases store data as fixed-size binary pages"],"correct":[0],"skill":1,"confidence":"high","set":null,"section":"1B","topic":"Relational vs Non-relational","sub":null,"explanation":"Relational databases store structured data in tables that reference one another by keys and are queried with SQL. Non-relational (NoSQL) databases don't apply a relational schema — common types are key-value, document, column family, and graph.","source":{"title":"Explore core data concepts: Explore databases (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/4-databases"}},{"id":"ml-104","sourceBank":"microsoft-learn","type":"single","question":"In the medallion architecture used to organize data in a lakehouse, which layer holds raw data ingested as-is with no transformations applied?","options":["Gold","Silver","Bronze","Platinum"],"correct":[2],"skill":1,"confidence":"high","set":null,"section":"1C","topic":"Medallion Architecture","sub":null,"explanation":"The medallion architecture uses three layers: Bronze (raw data ingested as-is, preserving original records), Silver (cleansed and conformed data), and Gold (aggregated, business-ready data modeled for reporting).","source":{"title":"Explore core data concepts: Analytical data processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-core-data-concepts/6-analytical-processing"}},{"id":"ml-105","sourceBank":"microsoft-learn","type":"single","question":"According to the course, how do data job roles relate to individual people?","options":["Each person can only ever perform one role","Roles define differentiated tasks; the same person might perform multiple roles in an organization","Roles are assigned automatically by Azure","Only large enterprises have any of these roles"],"correct":[1],"skill":1,"confidence":"high","set":null,"section":"1D","topic":"One Person, Multiple Roles","sub":null,"explanation":"The job roles define differentiated tasks and responsibilities, but in some organizations the same person might perform multiple roles — for example, acting as a database administrator and also as a data engineer.","source":{"title":"Explore data roles and services: Explore job roles (Training)","url":"https://learn.microsoft.com/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"ml-106","sourceBank":"microsoft-learn","type":"single","question":"A database administrator needs to grant a user permission to read and modify data in a table. Which group of SQL statements is used?","options":["Data Definition Language (DDL)","Data Manipulation Language (DML)","Data Control Language (DCL)","Query Optimization Language"],"correct":[2],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"DCL Statements","sub":null,"explanation":"DCL (Data Control Language) statements — GRANT, DENY, and REVOKE — manage access to objects by granting, denying, or revoking permissions. DBAs generally use DCL to control who can do what.","source":{"title":"Explore relational data: Explore SQL (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/4-query-with-sql"}},{"id":"ml-107","sourceBank":"microsoft-learn","type":"single","question":"Which database object encapsulates SQL statements that run on command and can accept parameters to perform common actions on data?","options":["A view","A stored procedure","An index","A primary key"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"Stored Procedures","sub":null,"explanation":"A stored procedure defines SQL statements that can be run on command, and can take parameters — encapsulating programmatic logic for actions applications need to perform, such as renaming a product by ID.","source":{"title":"Explore relational data: Describe database objects (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/5-database-objects"}},{"id":"ml-108","sourceBank":"microsoft-learn","type":"single","question":"Which SQL clause is used in a SELECT statement to combine rows from two tables based on a related column, typically matching a foreign key to a primary key?","options":["WHERE","ORDER BY","JOIN","GROUP BY"],"correct":[2],"skill":2,"confidence":"high","set":null,"section":"2A","topic":"JOIN Clause","sub":null,"explanation":"A JOIN clause indicates how rows in one table connect to rows in another to determine what data to return. A typical join condition matches a foreign key in one table to its associated primary key in the other.","source":{"title":"Explore relational data: Explore SQL (Training)","url":"https://learn.microsoft.com/training/modules/explore-relational-data-offerings/4-query-with-sql"}},{"id":"ml-109","sourceBank":"microsoft-learn","type":"single","question":"Which is an advantage of choosing a PaaS option (Azure SQL Database or SQL Managed Instance) over SQL Server on Azure VMs?","options":["You get full OS-level control","Microsoft handles patching, backups, and high availability, reducing administration overhead","It is the only option that can run SQL queries","It requires you to manage the virtual machine"],"correct":[1],"skill":2,"confidence":"high","set":null,"section":"2B","topic":"PaaS vs IaaS Responsibility","sub":null,"explanation":"With the PaaS options (SQL Database and SQL Managed Instance) you no longer manage the OS, hardware, or database engine — Microsoft handles patching, backups, and high availability — reducing administration overhead. SQL on VMs (IaaS) gives full control but adds responsibility.","source":{"title":"What is Azure SQL? (administration)","url":"https://learn.microsoft.com/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"ml-110","sourceBank":"microsoft-learn","type":"single","question":"Which type of Azure blob is optimized for append operations, where you can only add blocks to the end (useful for logging)?","options":["Block blob","Page blob","Append blob","Archive blob"],"correct":[2],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Blob Types","sub":null,"explanation":"An append blob is a block blob optimized to support append operations — you can only add blocks to the end; updating or deleting existing blocks isn't supported. Block blobs store discrete large objects; page blobs support random read/write (e.g., VM disks).","source":{"title":"Explore Azure Storage: Azure blob storage (Training)","url":"https://learn.microsoft.com/training/modules/explore-provision-deploy-non-relational-data-services-azure/2-azure-blob-storage"}},{"id":"ml-111","sourceBank":"microsoft-learn","type":"single","question":"How is data typically organized in an Azure Table storage table compared to a relational database?","options":["It is highly normalized with foreign keys and joins","It is usually denormalized, with each row holding the entire data for a logical entity and columns that can vary per row","It must use a fixed schema identical for every row","It supports stored procedures and views like a relational database"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3A","topic":"Table Storage — Denormalization","sub":null,"explanation":"Azure Table storage data is usually denormalized — each row holds all the data for a logical entity, and the columns can vary between rows. Tables have no foreign keys, relationships, stored procedures, or views.","source":{"title":"Explore Azure Storage: Azure Tables (Training)","url":"https://learn.microsoft.com/training/modules/explore-provision-deploy-non-relational-data-services-azure/5-azure-tables"}},{"id":"ml-112","sourceBank":"microsoft-learn","type":"single","question":"A team is migrating an existing MongoDB application to a fully managed Azure database with minimal code changes. Which Cosmos DB API should they use?","options":["API for NoSQL","API for MongoDB","API for Apache Gremlin","API for Table"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Cosmos DB APIs — MongoDB","sub":null,"explanation":"The API for MongoDB is compatible with MongoDB drivers and client libraries, so existing MongoDB applications can connect to Cosmos DB without significant code changes — a natural choice when migrating a MongoDB workload.","source":{"title":"Explore Cosmos DB: Identify Cosmos DB APIs (Training)","url":"https://learn.microsoft.com/training/modules/explore-non-relational-data-stores-azure/3-cosmos-db-apis"}},{"id":"ml-113","sourceBank":"microsoft-learn","type":"single","question":"In Azure Cosmos DB, what does the metric Request Units per second (RU/s) represent?","options":["The number of regions the data is replicated to","A measure of throughput/capacity, where every operation consumes some RU/s","The maximum size of a single document","The number of APIs enabled on the account"],"correct":[1],"skill":3,"confidence":"high","set":null,"section":"3B","topic":"Cosmos DB — Request Units","sub":null,"explanation":"Cosmos DB measures capacity in Request Units per second (RU/s) — roughly the cost of reading a 1-KB item. Every operation (read, write, query, delete) consumes RU/s, giving a single metric to reason about both performance and cost.","source":{"title":"Explore Cosmos DB: Describe Azure Cosmos DB (Training)","url":"https://learn.microsoft.com/training/modules/explore-non-relational-data-stores-azure/2-describe-azure-cosmos-db"}},{"id":"ml-114","sourceBank":"microsoft-learn","type":"single","question":"In Microsoft Fabric, what is OneLake?","options":["A relational OLTP database engine","A single, tenant-wide data lake that every Fabric workload shares, using Delta Lake as the standard format","A Power BI visualization type","A real-time event ingestion queue"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4A","topic":"OneLake & Direct Lake","sub":null,"explanation":"OneLake is the single, tenant-wide data lake shared across every Fabric workload. Instead of copying data between silos, every Fabric service reads from and writes to OneLake directly, using Delta Lake as the standard open format.","source":{"title":"Large-scale analytics: Analytical data stores (Training)","url":"https://learn.microsoft.com/training/modules/examine-components-of-modern-data-warehouse/4-analytical-data-stores"}},{"id":"ml-115","sourceBank":"microsoft-learn","type":"single","question":"Which architecture is a common pattern for combining batch and stream processing in a large-scale analytics solution?","options":["Star schema","Lambda architecture","Medallion tiers","Snowflake schema"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4B","topic":"Combining Batch and Stream","sub":null,"explanation":"The lambda architecture is a common pattern that combines a real-time (stream) path and a batch path — capturing streaming data for immediate analysis while also persisting data for later batch processing and historical analysis.","source":{"title":"Real-time analytics: Batch and stream processing (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-stream-processing/2-batch-stream"}},{"id":"ml-116","sourceBank":"microsoft-learn","type":"single","question":"After building reports in Power BI Desktop, where do you publish them so business users can interact with them, schedule data refreshes, and share dashboards?","options":["Azure Blob storage","The Power BI service (cloud)","Azure Data Factory","A Cosmos DB container"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4C","topic":"Power BI Service vs Desktop","sub":null,"explanation":"After creating models and reports in Power BI Desktop, you publish them to the Power BI service — a cloud service where reports can be consumed, data refreshes scheduled, and dashboards and apps shared with other users.","source":{"title":"Data visualization: Power BI tools and workflow (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-data-visualization/2-power-bi"}},{"id":"ml-117","sourceBank":"microsoft-learn","type":"single","question":"Which Power BI visualization is most useful for comparing two numeric measures to identify a relationship or correlation between them?","options":["Pie chart","Scatter plot","Table","Map"],"correct":[1],"skill":4,"confidence":"high","set":null,"section":"4C","topic":"Scatter Plots","sub":null,"explanation":"Scatter plots are useful when you want to compare two numeric measures and identify a relationship or correlation between them — for example, marketing spend versus revenue.","source":{"title":"Data visualization: Considerations for data visualization (Training)","url":"https://learn.microsoft.com/training/modules/explore-fundamentals-data-visualization/4-data-visualizations"}},{"id":"gen-1","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retailer exports its daily sales as a CSV file in which every row has the exact same columns (OrderID, ProductID, Quantity, Price) and each column always holds the same data type. How should this data be classified?","options":["Structured data","Semi-structured data","Unstructured data","Vector data"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Data that fits a fixed, predefined schema of identical rows and columns is structured (tabular) data. Classification follows the data's shape, not the fact that it arrives as a file.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-2","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An e-commerce application stores each order as a JSON document, and different orders can carry different optional fields such as a gift note or a coupon code. Which category of data representation is this?","options":["Structured data","Semi-structured data","Unstructured data","Relational data"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"JSON documents have organizing keys and can nest and vary between records, but they do not conform to a rigid predefined table, which makes them semi-structured, self-describing data.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-3","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A media company needs to store thousands of raw video files and high-resolution product photos cheaply and serve them to a web app. Which Azure storage service is optimized for this kind of data?","options":["Azure SQL Database","Azure Table storage","Azure Blob Storage","Azure Cache for Redis"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Videos and images are unstructured data with no queryable schema. Azure Blob Storage is object storage optimized for storing massive amounts of unstructured data.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-4","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants to build a semantic search feature that finds support articles by meaning rather than exact keyword matches. Which form of data representation directly enables this similarity search?","options":["Structured tabular data","Semi-structured XML","Unstructured binary blobs","Vector data (embeddings)"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Vector data consists of numeric arrays (embeddings) that represent the meaning of content such as text or images, so items with similar meaning sit close together and can be found by similarity search.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-5","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes how Azure Table storage represents the data it holds?","options":["It stores structured, non-relational key/attribute data (structured NoSQL)","It stores fully relational data with enforced foreign keys","It stores unstructured binary objects such as images and video","It stores message payloads for asynchronous processing"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Table storage is a NoSQL key/attribute store that holds structured, non-relational data; entities have properties but there is no enforced relational schema across tables.","source":{"title":"Introduction to Azure Table storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"}},{"id":"gen-6","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data team stores raw files as-is in a data lake and only applies structure to them at the moment they are queried. Which approach does this describe?","options":["Schema-on-write","Schema-on-read","Normalization","Referential integrity"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Schema-on-read stores data in its original form and applies a structure only when the data is read, which is typical of semi-structured and unstructured data in file stores and data lakes.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-7","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following is the best example of unstructured data?","options":["A CSV file with fixed columns","A JSON document with nested fields","A relational customer table","A scanned PDF contract and an audio recording"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Documents, images, audio, and video have no predefined data model you can query by field, so they are unstructured. A CSV is structured and JSON is semi-structured.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-8","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A colleague argues that because a CSV file is stored as a file rather than in a database, it must be unstructured data. Why is this reasoning incorrect?","options":["CSV files are always semi-structured because they are text","Data classification depends on the data's shape (fixed rows and columns), not where it is stored","Any file stored outside a relational database is unstructured","CSV files become structured only after being imported into SQL"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Whether data is structured, semi-structured, or unstructured depends on its shape, not its storage location. A CSV with a fixed set of columns is structured tabular data even though it lives in a file.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-9","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which set of formats are all commonly used to represent semi-structured data?","options":["PNG, MP4, WAV","CSV, XLSX, TSV","JPG, PDF, DOCX","JSON, XML, YAML"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"JSON, XML, and YAML are self-describing formats that carry organizing tags or keys and allow varying, nestable fields, which makes them semi-structured rather than rigidly tabular.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-10","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization needs to store IoT telemetry where each device message is a self-describing document whose fields vary from one device model to another. How is this data best characterized?","options":["Unstructured data","Structured data","Semi-structured data","Vector data"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Messages that carry their own field names and can differ in which fields are present are semi-structured; they have some structure but do not fit a single fixed table schema.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-11","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which characteristic most accurately defines structured data?","options":["It carries its own field names inside each record and can nest","It has no schema that can be queried by field","It is always stored only inside a relational database engine","It conforms to a fixed, predefined schema of rows and columns"],"correct":[3],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Structured data conforms to a fixed, predefined schema where every row has the same columns and data types. It can be stored in relational databases, spreadsheets, or delimited files.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-12","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Azure Blob Storage is described as being optimized for which primary type of data?","options":["Highly normalized relational tables","Large amounts of unstructured data","Semi-structured graph relationships","Real-time streaming message queues"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Blob storage is object storage designed to hold massive amounts of unstructured data such as text or binary data, including images, video, documents, and backups.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-13","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A structured, non-relational dataset must be stored as key/attribute entities that can be retrieved quickly by key, without the overhead of a relational schema. Which Azure service is designed for this?","options":["Azure Table storage","Azure Blob Storage","Azure Queue storage","Azure Files"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Table storage is a NoSQL store for structured, non-relational data organized as entities with properties, ideal for fast key-based lookups without a fixed relational schema.","source":{"title":"Introduction to Azure Table storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"}},{"id":"gen-14","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"How does vector data relate to the three primary categories of data representation?","options":["It replaces the unstructured category entirely","It is a fourth category that only applies to relational tables","It builds on unstructured content by encoding its meaning as numeric embeddings","It is another name for semi-structured JSON"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Vector data represents the meaning of unstructured content such as text or images as numeric arrays (embeddings) for similarity search; it builds on the unstructured category rather than replacing it.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-15","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When structure is enforced at the moment data is written and records that do not fit the schema are rejected, which approach is being used?","options":["Schema-on-read","Schema-on-write","Denormalization","Sharding"],"correct":[1],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Schema-on-write validates and enforces the structure as data is stored, which is characteristic of structured data in relational databases; data that does not conform is rejected.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-16","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A photographer wants to archive millions of RAW image files in Azure as individual objects that are written once and rarely modified. Which combination of data representation and storage is most appropriate?","options":["Semi-structured data in Azure Table storage","Structured data in Azure SQL Database","Unstructured data in Azure Blob Storage","Vector data in a relational table"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Image files have no queryable field schema, so they are unstructured, and Azure Blob Storage (object storage) is the service optimized for storing large volumes of such objects.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-17","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement about JSON is correct for the DP-900 exam?","options":["JSON is unstructured because it is stored as text","JSON is structured because it always fits a fixed table","JSON is semi-structured because it has keys and nesting but no rigid table schema","JSON is vector data because it can represent meaning"],"correct":[2],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"JSON is a self-describing format with keys and nestable, varying fields. It has organizing structure but does not conform to a fixed relational table, so it is classified as semi-structured.","source":{"title":"Identify data formats — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/2-data-formats"}},{"id":"gen-18","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Even though Azure Table storage is a NoSQL, non-relational service, the data it stores is often described using which term?","options":["Structured (structured NoSQL) data","Purely unstructured data","Streaming event data","Vector embedding data"],"correct":[0],"skill":1,"sub":"1.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Table storage holds entities with defined properties, so its data is structured even though the service is non-relational NoSQL; it is commonly called structured NoSQL data.","source":{"title":"Introduction to Azure Table storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"}},{"id":"gen-19","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data engineer needs to export a table of sales records so it can be opened in Excel and imported by many different tools. Each row must be on its own line with fields separated by commas. Which file format best fits this requirement?","options":["Delimited text (CSV)","Parquet","Avro","Portable Network Graphics (PNG)"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Delimited text such as CSV stores tabular data as plain-text rows with a delimiter (a comma) between field values, making it widely portable and readable by tools like Excel.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-20","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An application must persist objects that contain nested properties and arrays, where different records may have different fields. The team wants a human-readable, text-based format commonly used for semi-structured data. Which format should they choose?","options":["Fixed-width delimited text","JSON","Page blob","ORC"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"JSON is a text-based, human-readable format that represents entities with nested objects and arrays, making it a common choice for semi-structured data where records can vary in structure.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-21","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A big-data pipeline continuously appends new records and needs a compact, schema-embedded, row-based binary format that is efficient for write-heavy workloads. Which file format is the best match?","options":["CSV","Parquet","Avro","XML"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Avro is a row-based binary format that stores the schema in the file header (as JSON) and is well suited to write-heavy scenarios where whole rows are appended.","source":{"title":"Azure Data Lake Storage introduction — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction"}},{"id":"gen-22","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An analytics team runs queries that read only a few columns from very large datasets and wants a columnar format that compresses well and is optimized for analytical read performance. Which format should they use?","options":["Delimited text (TSV)","JSON","Avro","Parquet"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Parquet is a columnar storage format that stores data by column, enabling efficient compression and fast reads when queries select only specific columns of large analytical datasets.","source":{"title":"Azure Data Lake Storage introduction — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction"}},{"id":"gen-23","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes the primary difference between storing data in a file store versus storing it in a database?","options":["A file store holds data as files that applications must parse themselves, while a database organizes data and provides a management system to query and manage it","A file store can only hold images, while a database can only hold text","A file store enforces relationships between tables, while a database cannot","A file store guarantees ACID transactions, while a database does not"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"File storage keeps data as discrete files that consuming applications must interpret, whereas a database organizes data through a schema and provides a database management system for querying, updating, and managing it.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-24","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A solution stores catalog items as documents where each item can have a different set of attributes and there is no fixed tabular schema enforced across all records. This is an example of which kind of data store?","options":["A relational database","A non-relational (NoSQL) database","A page blob","A delimited text file"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Non-relational (NoSQL) databases do not enforce a single fixed tabular schema, so each entity or document can contain a different set of fields, which suits variable catalog data.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-25","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization needs a data store that enforces a fixed schema of tables with defined columns and relationships, and supports SQL queries with strong consistency for transactions. Which type of data store meets these needs?","options":["Azure Queue storage","A data lake","A relational database","Azure Table storage"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A relational database organizes data into tables with a predefined schema of columns and relationships, and is designed for SQL querying with transactional consistency.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-26","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team needs to store large numbers of documents, images, and video files as objects that applications and services can access over HTTP/HTTPS. Which Azure storage option is optimized for this unstructured data?","options":["Azure Table storage","Azure SQL Database","Azure Queue storage","Azure Blob storage"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Blob storage is object storage optimized for holding massive amounts of unstructured data such as documents, images, and video, accessible over HTTP/HTTPS.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-27","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An administrator needs to store virtual hard disk (VHD) files that back Azure virtual machine disks and require frequent random read/write access to ranges within the file. Which type of blob is designed for this scenario?","options":["Page blobs","Append blobs","Block blobs","Table entities"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Page blobs store random-access files up to 8 TB and are used for VHD files that back Azure virtual machine disks, supporting efficient reads and writes to ranges within the blob.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-28","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A logging service continuously adds new log entries to the end of a file and never modifies existing content. Which Azure blob type is optimized for these append operations?","options":["Page blobs","Append blobs","Block blobs","Queue messages"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Append blobs are optimized for append operations, making them ideal for scenarios such as logging where data is added to the end of the blob and existing blocks are not modified.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-29","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company keeps blobs that are rarely accessed and can tolerate hours of retrieval latency, and wants the lowest storage cost. Which Azure Blob storage access tier should they choose for this data?","options":["Hot tier","Cool tier","Archive tier","Premium tier"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The archive tier offers the lowest storage cost for rarely accessed data that can tolerate retrieval latency of several hours while the blob is rehydrated.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-30","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Azure Blob storage, how are blobs organized within a storage account?","options":["Blobs are stored directly at the storage account root with no grouping","Blobs are stored inside tables, which are stored in partitions","Blobs are stored inside queues, which are stored in shares","Blobs are stored in containers, which reside within a storage account"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A storage account contains containers, and each container holds blobs; this container-and-blob hierarchy is the object model Blob storage uses to organize data.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-31","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A big-data team wants Blob storage to support a true directory structure so that operations like renaming or deleting a folder are atomic and file-system-aware analytics engines perform better. Which capability should be enabled on the storage account?","options":["Hierarchical namespace (Azure Data Lake Storage Gen2)","Soft delete for blobs","Point-in-time restore","Change feed"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Data Lake Storage Gen2 adds a hierarchical namespace on top of Blob storage, organizing objects into a true directory structure so folder-level operations are atomic and efficient for big-data analytics.","source":{"title":"Azure Data Lake Storage introduction — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction"}},{"id":"gen-32","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An enterprise wants a single, highly scalable repository to hold large volumes of raw data in many formats (CSV, JSON, Parquet) for later processing by big-data analytics frameworks such as Spark and Hadoop. Which Azure option is designed for this purpose?","options":["Azure Queue storage","Azure Data Lake Storage","Azure Table storage","Azure Files"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Data Lake Storage is built to hold large volumes of data in many file formats and integrates with big-data analytics frameworks such as Spark and Hadoop for large-scale processing.","source":{"title":"Azure Data Lake Storage introduction — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction"}},{"id":"gen-33","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer needs a low-cost store for large numbers of entities where each entity is a set of key/attribute pairs identified by a key, with no need for relational joins or a fixed schema. Which Azure storage service fits this NoSQL requirement?","options":["Azure Blob storage","Azure SQL Managed Instance","Azure Table storage","Azure Files"],"correct":[2],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Table storage is a NoSQL key/attribute store that holds large volumes of schemaless entities, each a set of properties identified by a key, without relational joins.","source":{"title":"Azure Table storage overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"}},{"id":"gen-34","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Azure Table storage, which combination uniquely identifies an entity and determines how data is grouped for scalability?","options":["A primary key column and a foreign key column","A container name and a blob name","A queue name and a message ID","A partition key and a row key"],"correct":[3],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Table storage uses a partition key to group related entities for scalability and a row key to uniquely identify each entity within a partition; together they form the entity's unique key.","source":{"title":"Azure Table storage overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"}},{"id":"gen-35","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A dataset consists of digital photographs and audio recordings that have no inherent tabular or field-based structure. How is this type of data classified, and which Azure store is most appropriate?","options":["Unstructured data, best stored in Azure Blob storage","Structured data, best stored in a relational database","Semi-structured data, best stored in Azure Table storage","Structured data, best stored in Azure Files as a schema"],"correct":[0],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Media files such as photos and audio have no defined tabular structure, so they are unstructured data, which is best kept in object storage like Azure Blob storage.","source":{"title":"Introduction to Azure Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-36","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team is deciding how to store data that arrives as JSON documents whose fields vary between records. Which description correctly characterizes this data?","options":["It is structured data because every record must have identical columns","It is semi-structured data because it has tags or keys that organize fields, but no rigid tabular schema","It is unstructured data because it contains no organizing elements at all","It is binary data that cannot be read as text"],"correct":[1],"skill":1,"sub":"1.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Semi-structured data such as JSON uses keys or tags to organize its fields but does not enforce the rigid, uniform tabular schema of structured data, so records can vary.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-37","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retail company runs a point-of-sale system that records every individual purchase the moment a customer checks out, inserting one row per sale into a database. Which type of data workload does this system primarily represent?","options":["Analytical (OLAP) processing","Batch reporting workload","Transactional (OLTP) processing","Data visualization workload"],"correct":[2],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Capturing each individual purchase as it happens, with frequent small inserts, is transactional (OLTP) processing that records the day-to-day operations of the business.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-38","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In transactional (OLTP) systems, the acronym ACID describes the guarantees that each transaction must meet. What do the letters ACID stand for?","options":["Atomicity, Consistency, Isolation, Durability","Accuracy, Concurrency, Integrity, Distribution","Availability, Caching, Indexing, Deduplication","Aggregation, Consolidation, Integration, Delivery"],"correct":[0],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"OLTP systems enforce ACID semantics — Atomicity, Consistency, Isolation, and Durability — so that each transaction is processed reliably as a single unit of work.","source":{"title":"Online transaction processing (OLTP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-transaction-processing"}},{"id":"gen-39","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business intelligence team needs to analyze five years of historical sales data to identify seasonal trends across regions and product categories. Which type of data workload best fits this requirement?","options":["Transactional (OLTP) processing","Message queuing workload","File synchronization workload","Analytical (OLAP) processing"],"correct":[3],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Aggregating large volumes of historical data to identify trends and support decision-making is an analytical (OLAP) workload rather than a transactional one.","source":{"title":"Online analytical processing (OLAP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-analytical-processing"}},{"id":"gen-40","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which characteristic most accurately describes the typical read/write pattern of an OLTP database compared with an OLAP system?","options":["OLTP is read-only while OLAP is write-heavy","OLTP handles many small, frequent read/write transactions while OLAP is read-heavy over large datasets","Both OLTP and OLAP are optimized only for bulk batch writes","OLTP performs complex multi-table aggregations while OLAP handles single-row inserts"],"correct":[1],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"OLTP workloads consist of large numbers of small, frequent create/read/update/delete transactions, whereas OLAP workloads are read-intensive, running complex queries over large historical datasets.","source":{"title":"Online transaction processing (OLTP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-transaction-processing"}},{"id":"gen-41","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"To reduce data redundancy and avoid update anomalies, OLTP relational databases are commonly designed using which technique?","options":["Star schema denormalization","Columnar compression","Normalization","Data lake partitioning"],"correct":[2],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"OLTP databases are typically normalized to minimize data duplication and maintain integrity during frequent inserts and updates.","source":{"title":"Online transaction processing (OLTP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-transaction-processing"}},{"id":"gen-42","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization wants to move historical operational data into a dedicated store optimized for reporting so that heavy analytical queries do not slow down the live order-entry application. What is the primary reason for keeping analytical processing separate from transactional processing?","options":["Analytical queries can only run on unstructured data","OLTP databases cannot store historical data","Long-running analytical queries could degrade performance of the transactional system","Transactional systems cannot use SQL"],"correct":[2],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Separating analytical workloads from transactional ones prevents resource-intensive, long-running analytical queries from impacting the responsiveness of the OLTP system that supports day-to-day operations.","source":{"title":"Online analytical processing (OLAP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-analytical-processing"}},{"id":"gen-43","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"OLAP systems often pre-aggregate data into a semantic model or cube. What is the main benefit of this approach?","options":["It guarantees ACID compliance for individual writes","It enables fast responses to complex analytical queries and aggregations","It removes the need to store any historical data","It converts unstructured data into transactions"],"correct":[1],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"OLAP models pre-aggregate and structure data (for example into cubes or semantic models) so that complex aggregations and slice-and-dice analysis return quickly.","source":{"title":"Online analytical processing (OLAP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-analytical-processing"}},{"id":"gen-44","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A banking application must ensure that when money is transferred between two accounts, either both the debit and the credit succeed together or neither is applied. Which ACID property guarantees this all-or-nothing behavior?","options":["Durability","Isolation","Consistency","Atomicity"],"correct":[3],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Atomicity ensures that a transaction is treated as a single indivisible unit — all of its operations succeed together or none are applied.","source":{"title":"Online transaction processing (OLTP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-transaction-processing"}},{"id":"gen-45","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following scenarios is the best example of a transactional (OLTP) workload?","options":["Building a year-over-year revenue dashboard for executives","An e-commerce site updating inventory as each order is placed","Training a machine learning model on ten years of sales history","Generating a quarterly summary report of regional performance"],"correct":[1],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Updating inventory in real time as individual orders are placed is a classic OLTP workload built on frequent, small transactions.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-46","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"How does the data typically flow in an analytical processing environment before it becomes available for reporting?","options":["Data is queried directly from operational sources with no preparation","Data is captured, ingested, transformed, and loaded into an analytical store, then modeled and visualized","Data is only ever stored as individual transactions and never aggregated","Data is written back to the source system after every query"],"correct":[1],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Analytical processing usually follows a pipeline: operational data is captured, ingested and transformed, loaded into an analytical data store, then modeled and visualized for reporting.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-47","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which ACID property ensures that once a transaction has been committed, its changes remain in place even if the system subsequently crashes or loses power?","options":["Durability","Isolation","Atomicity","Consistency"],"correct":[0],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Durability guarantees that committed transactions are permanently saved and survive system failures such as crashes or power loss.","source":{"title":"Online transaction processing (OLTP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-transaction-processing"}},{"id":"gen-48","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An OLAP data store used for analytics is often described as read-heavy. Why is it usually acceptable that data in such a store is not always up to the second?","options":["Because OLAP stores cannot accept any new data once created","Because analytical reporting focuses on trends over time rather than the latest individual transaction","Because OLAP stores only contain unstructured data","Because analytical queries must run inside the transactional database"],"correct":[1],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Analytical workloads emphasize historical trends and aggregations, so a slight lag from periodic loads is acceptable because up-to-the-second accuracy is not the goal.","source":{"title":"Online analytical processing (OLAP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-analytical-processing"}},{"id":"gen-49","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which ACID property ensures that concurrently running transactions do not interfere with one another, so each behaves as if it were executing alone?","options":["Consistency","Durability","Isolation","Atomicity"],"correct":[2],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Isolation ensures that concurrent transactions are kept separate so that the intermediate state of one does not affect another.","source":{"title":"Online transaction processing (OLTP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-transaction-processing"}},{"id":"gen-50","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data analyst runs a query that summarizes total sales by product category, region, and month across millions of historical records. This type of query is most characteristic of which workload?","options":["Analytical (OLAP) processing","Transactional (OLTP) processing","Real-time message queuing","Single-record key lookup"],"correct":[0],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Complex aggregations that summarize large volumes of historical data across multiple dimensions are the hallmark of analytical (OLAP) processing.","source":{"title":"Online analytical processing (OLAP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-analytical-processing"}},{"id":"gen-51","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best contrasts the primary optimization goal of OLTP systems with that of OLAP systems?","options":["Both are optimized for storing unstructured media files","OLTP is optimized for fast, reliable individual transactions; OLAP is optimized for complex queries over large aggregated datasets","OLTP is optimized for long-running batch analytics; OLAP is optimized for single-row updates","OLTP is optimized for data visualization; OLAP is optimized for message delivery"],"correct":[1],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"OLTP is tuned for fast, reliable processing of many small transactions, while OLAP is tuned for read-heavy, complex analytical queries over large, aggregated datasets.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-52","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In an OLAP schema, data is frequently organized around central fact tables surrounded by dimension tables. This design is commonly referred to as which pattern?","options":["Third normal form","Message queue pattern","Star (or snowflake) schema","Append-only log"],"correct":[2],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Analytical stores are often modeled as star or snowflake schemas, with fact tables holding measures and surrounding dimension tables providing context for aggregation.","source":{"title":"Online analytical processing (OLAP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-analytical-processing"}},{"id":"gen-53","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following best describes the kind of data that transactional processing systems primarily work with?","options":["Pre-aggregated summaries prepared for executive dashboards","Historical snapshots loaded once per quarter","The current, up-to-date records that reflect the live operations of a business","Read-only archives that are never modified"],"correct":[2],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Transactional systems manage the live, current data that reflects the ongoing operations of an organization, supporting frequent inserts, updates, and deletes.","source":{"title":"Explore core data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-core-data-concepts/"}},{"id":"gen-54","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which ACID property ensures that a transaction moves the database from one valid state to another, never leaving it violating defined rules or constraints?","options":["Isolation","Atomicity","Durability","Consistency"],"correct":[3],"skill":1,"sub":"1.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Consistency guarantees that every committed transaction leaves the database in a valid state that satisfies all defined rules and constraints.","source":{"title":"Online transaction processing (OLTP) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/architecture/data-guide/relational-data/online-transaction-processing"}},{"id":"gen-55","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retail company needs someone to design and build the pipelines that ingest raw sales data from multiple sources, clean it, transform it, and load it into an analytical data store. Which data role is primarily responsible for this work?","options":["Database administrator","Data engineer","Data analyst","Data steward"],"correct":[1],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A data engineer designs and builds data pipelines that ingest, integrate, transform, and consolidate data from various sources into analytical data stores for downstream use.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-56","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization needs a professional to ensure its databases are available, backed up regularly, and that user access and permissions are correctly configured. Which role best matches these responsibilities?","options":["Data engineer","Data analyst","Database administrator","AI engineer"],"correct":[2],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A database administrator manages databases, assigning permissions to users, storing backup copies of data, and restoring data in case of failures, while keeping the database available and performing.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-57","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business wants someone to build reports and dashboards in Power BI that turn cleaned data into charts and insights that help managers make decisions. Which data role is responsible for this?","options":["Data analyst","Database administrator","Data engineer","Solution architect"],"correct":[0],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A data analyst explores and analyzes data to identify trends and creates visualizations, reports, and dashboards that communicate insights to support business decisions.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-58","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which sequence correctly describes the typical order in which the three main data roles handle data?","options":["Data analyst cleans data, then the database administrator visualizes it, then the data engineer secures it","Data engineer ingests and transforms data, database administrator manages the stores, and the data analyst reports on it","Database administrator ingests data, data analyst transforms it, data engineer builds pipelines","Data analyst ingests data, data engineer secures it, database administrator visualizes it"],"correct":[1],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Data engineers build the pipelines that ingest and transform data, database administrators manage and secure the databases, and data analysts explore that data to produce reports and visualizations.","source":{"title":"Explore data roles and services — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/"}},{"id":"gen-59","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A database administrator is asked to reduce the risk of permanent data loss if a server fails. Which responsibility most directly addresses this concern?","options":["Building ETL pipelines to move data between systems","Creating Power BI dashboards for executives","Implementing and testing backup and restore procedures","Designing the star schema for a data warehouse"],"correct":[2],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A core database administrator responsibility is backing up data and being able to restore it in the event of a failure, protecting against data loss.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-60","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data engineer at a manufacturing firm needs a cloud service to orchestrate pipelines that extract, transform, and load data from many sources on a schedule. Which Azure service is most appropriate?","options":["Azure Data Factory","Power BI","Azure Table storage","Microsoft Entra ID"],"correct":[0],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Data Factory is a cloud-based data integration service that data engineers use to create pipelines that ingest, transform, and orchestrate the movement of data between stores.","source":{"title":"Identify data services — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/3-data-services"}},{"id":"gen-61","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which task falls OUTSIDE the typical responsibilities of a data analyst?","options":["Creating charts and dashboards to visualize data","Identifying trends and relationships in datasets","Modeling data to support reporting","Configuring high availability and failover for a production database"],"correct":[3],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Configuring high availability and failover is a database administrator responsibility. Data analysts focus on exploring, modeling, and visualizing data to surface insights.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-62","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company is standing up a new analytics platform and needs someone to integrate data from an on-premises SQL Server, a REST API, and blob storage into a single analytical store. Which role should be assigned this task?","options":["Database administrator","Data analyst","Data engineer","Business user"],"correct":[2],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Integrating and consolidating data from multiple disparate sources into an analytical store is a defining responsibility of a data engineer.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-63","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data analyst needs a tool to model cleaned data, build interactive reports, and share dashboards with business stakeholders. Which Microsoft product is designed for this?","options":["Microsoft Power BI","Azure Data Factory","Azure SQL Managed Instance","Azure Blob Storage"],"correct":[0],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power BI is Microsoft's data visualization and reporting platform that data analysts use to model data and create interactive reports and dashboards.","source":{"title":"Identify data services — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/3-data-services"}},{"id":"gen-64","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best distinguishes a data engineer from a database administrator?","options":["Both roles focus exclusively on building visualizations","The data engineer builds and manages data pipelines and processing, while the database administrator manages the availability, security, and performance of databases","The database administrator builds ETL pipelines, while the data engineer only creates reports","There is no meaningful difference; the titles are interchangeable"],"correct":[1],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Data engineers build and operate data pipelines and processing systems, whereas database administrators manage the databases themselves, ensuring availability, security, backups, and performance.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-65","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A database administrator is granting each application service account only the minimum permissions it needs to function. Which category of responsibility does this activity fall under?","options":["Data visualization","Pipeline orchestration","Managing security and user access","Trend analysis"],"correct":[2],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Assigning and managing permissions and controlling access to data is part of the database administrator's responsibility for database security.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-66","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team needs to provision and manage relational databases in Azure, handling backups and access control. Which combination of role and service is most appropriate?","options":["Data analyst using Power BI","Data engineer using Event Hubs","Database administrator using Azure SQL Database","Data analyst using Azure Data Factory"],"correct":[2],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Database administrators manage databases such as Azure SQL Database, handling provisioning, security, backups, and availability of the relational data store.","source":{"title":"Identify data services — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/3-data-services"}},{"id":"gen-67","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Business stakeholders complain they cannot understand raw tables of numbers and want them turned into clear visual insights. Which role is best suited to meet this need?","options":["Database administrator","Data analyst","Data engineer","Network administrator"],"correct":[1],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A data analyst turns data into insight by creating visualizations, reports, and dashboards that make information understandable and actionable for business users.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-68","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following is a primary responsibility of a data engineer?","options":["Approving budget for new hardware purchases","Designing and implementing data ingestion and transformation processes","Writing marketing copy for product launches","Answering customer support tickets"],"correct":[1],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Data engineers are responsible for designing and implementing the processes that ingest, transform, and load data so it is ready for analysis.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-69","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization is mapping roles to the services they most commonly use. Which pairing is correct?","options":["Data engineer — Power BI reports; Data analyst — Azure Data Factory pipelines","Database administrator — Azure SQL databases; Data analyst — Power BI","Data analyst — database backup and restore; Database administrator — dashboards","Data engineer — assigning database permissions; Database administrator — building pipelines"],"correct":[1],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Database administrators primarily work with database services such as Azure SQL Database, while data analysts primarily use Power BI to model and visualize data.","source":{"title":"Identify data services — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/3-data-services"}},{"id":"gen-70","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A monitoring alert shows a production database is running slowly and queries are timing out. Which role is primarily responsible for investigating and tuning database performance?","options":["Data analyst","Data engineer","Database administrator","Report author"],"correct":[2],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Ensuring the database performs well and remains available, including monitoring and tuning performance, is a core database administrator responsibility.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-71","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a typical modern data workflow, which role prepares and consolidates the data so that it is in a suitable state for the data analyst to build reports from?","options":["Data engineer","Database administrator","Data analyst","Security administrator"],"correct":[0],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The data engineer builds the pipelines that ingest, transform, and consolidate data into analytical stores, preparing it so the data analyst can explore and visualize it.","source":{"title":"Explore data roles and services — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/"}},{"id":"gen-72","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A candidate says their job is to explore data, apply data modeling, and combine data to produce reports that help a business make decisions. Which role are they describing?","options":["Database administrator","Data engineer","Data analyst","Data pipeline operator"],"correct":[2],"skill":1,"sub":"1.4","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A data analyst explores and models data and creates reports and visualizations that help the business identify trends and make informed decisions.","source":{"title":"Explore job roles — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-roles-responsibilities-world-of-data/2-explore-job-roles"}},{"id":"gen-73","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retail company stores customer orders in a relational database. Each order must reference a valid customer that already exists in the customers table. Which relational feature enforces this rule so an order cannot reference a non-existent customer?","options":["A foreign key constraint","A clustered index","A stored procedure","A partition scheme"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A foreign key links a column in one table to the primary key of another, enforcing referential integrity so a child row can only reference an existing parent row.","source":{"title":"Explore fundamental relational data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-relational-data-offerings/"}},{"id":"gen-74","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a relational table, which characteristic best describes how data is organized?","options":["As a collection of key-value pairs with no fixed structure","As nested JSON documents of varying shape","As rows and columns where every row has the same set of columns","As a graph of nodes connected by edges"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Relational data is structured as tables of rows (records) and columns (fields), where every row in a table shares the same columns and data types.","source":{"title":"Explore fundamental relational data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-relational-data-offerings/"}},{"id":"gen-75","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A database designer wants to reduce duplicate data and avoid update anomalies by splitting information into related tables. What is this process called?","options":["Denormalization","Indexing","Normalization","Partitioning"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Normalization is the design process of organizing data into related tables to minimize duplication and reduce the risk of data inconsistencies.","source":{"title":"Explore fundamental relational data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-relational-data-offerings/"}},{"id":"gen-76","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which SQL statement type is used to change data that already exists in a table without adding or removing rows?","options":["UPDATE","INSERT","CREATE","DROP"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"UPDATE is a data manipulation (DML) statement that modifies the values in existing rows; INSERT adds rows and DELETE removes them.","source":{"title":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/t-sql/language-reference"}},{"id":"gen-77","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An analyst needs to retrieve specific columns from a table for reporting but must not modify any stored data. Which SQL statement should be used?","options":["ALTER","SELECT","DELETE","GRANT"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"SELECT is the query statement used to read and return data from tables without changing it.","source":{"title":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/t-sql/language-reference"}},{"id":"gen-78","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"The statements CREATE, ALTER, and DROP that define or change the structure of database objects belong to which category of SQL?","options":["Data Control Language (DCL)","Data Manipulation Language (DML)","Transaction Control Language (TCL)","Data Definition Language (DDL)"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"DDL statements such as CREATE, ALTER, and DROP define and modify the schema and structure of database objects like tables and views.","source":{"title":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/t-sql/language-reference"}},{"id":"gen-79","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A DBA needs to give a specific user permission to query a table while denying update rights. Which category of SQL statements is used to manage these permissions?","options":["Data Manipulation Language (DML), using SELECT and UPDATE","Data Definition Language (DDL), using CREATE and ALTER","Query language, using SELECT only","Data Control Language (DCL), using GRANT and REVOKE"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"DCL statements such as GRANT, REVOKE, and DENY manage permissions and access rights to database objects.","source":{"title":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/t-sql/language-reference"}},{"id":"gen-80","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team frequently runs the same complex multi-step query and wants to save it as a reusable, precompiled routine that can accept parameters. Which database object best fits this need?","options":["An index","A view","A stored procedure","A primary key"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A stored procedure is a saved, reusable set of SQL statements that can accept parameters and encapsulate business logic on the database server.","source":{"title":"Stored procedures (Database Engine) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/relational-databases/stored-procedures/stored-procedures-database-engine"}},{"id":"gen-81","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A reporting team should see only three columns from a large customer table and should not access the underlying table directly. Which database object provides this saved, virtual result set?","options":["A trigger","A foreign key","A view","A clustered index"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A view is a virtual table defined by a stored SELECT query; it can expose a subset of columns and rows without giving direct access to the base table.","source":{"title":"Views — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/relational-databases/views/views"}},{"id":"gen-82","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which database object is designed primarily to improve the speed of data retrieval by allowing the engine to locate rows without scanning the entire table?","options":["A view","A stored procedure","An index","A constraint"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An index provides a fast lookup structure so the database can find rows quickly instead of scanning every row in the table.","source":{"title":"Explore fundamental relational data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-relational-data-offerings/"}},{"id":"gen-83","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a normalized relational database, what is the purpose of a primary key?","options":["To store a copy of data from another table for faster reads","To grant users permission to access the table","To automatically delete old rows on a schedule","To uniquely identify each row in a table"],"correct":[3],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A primary key is a column (or set of columns) whose value uniquely identifies each row in a table and cannot be duplicated or null.","source":{"title":"Explore fundamental relational data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-relational-data-offerings/"}},{"id":"gen-84","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which SQL statement would an administrator use to permanently remove an entire table, including its structure, from the database?","options":["DELETE","TRUNCATE","DROP","UPDATE"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"DROP is a DDL statement that removes an object such as a table entirely, including its definition; DELETE and TRUNCATE only remove rows, leaving the table structure in place.","source":{"title":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/t-sql/language-reference"}},{"id":"gen-85","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A developer wants to add a new customer record to the customers table. Which SQL statement is appropriate?","options":["INSERT","SELECT","ALTER","REVOKE"],"correct":[0],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"INSERT is the DML statement used to add new rows of data into a table.","source":{"title":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/t-sql/language-reference"}},{"id":"gen-86","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"One benefit of normalizing a relational database is that it reduces data redundancy. Which additional benefit does normalization typically provide?","options":["It removes the need for any indexes","It improves data consistency by storing each fact in one place","It converts the database into unstructured storage","It eliminates the need for primary and foreign keys"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"By storing each piece of information once, normalization improves consistency and reduces update anomalies, since a value only needs to be changed in a single location.","source":{"title":"Explore fundamental relational data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-relational-data-offerings/"}},{"id":"gen-87","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which set of SQL statements are all classified as Data Manipulation Language (DML)?","options":["CREATE, ALTER, DROP","GRANT, REVOKE, DENY","SELECT, INSERT, UPDATE, DELETE","BEGIN, COMMIT, ROLLBACK"],"correct":[2],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"DML statements work with the data in tables: SELECT reads, INSERT adds, UPDATE modifies, and DELETE removes rows.","source":{"title":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/t-sql/language-reference"}},{"id":"gen-88","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An application repeatedly executes a stored procedure instead of sending raw ad-hoc SQL from the client. Which advantage does using the stored procedure provide?","options":["It stores data in an unstructured format","It encapsulates logic on the server and can be reused with parameters","It removes the need for a primary key on tables","It automatically converts the database to non-relational"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A stored procedure centralizes SQL logic on the server, can accept parameters, and is reusable, which improves consistency and reduces repeated client-side code.","source":{"title":"Stored procedures (Database Engine) — Microsoft Learn","url":"https://learn.microsoft.com/en-us/sql/relational-databases/stored-procedures/stored-procedures-database-engine"}},{"id":"gen-89","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a relational model, what does a single column in a table represent?","options":["A complete record for one entity instance","A specific attribute or field that is the same across all rows","A relationship between two separate tables","A stored query that returns data on demand"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A column represents a single attribute (field) of the entity, holding the same type of value for every row in the table, while a row represents one record.","source":{"title":"Explore fundamental relational data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-relational-data-offerings/"}},{"id":"gen-90","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company defines each product once in a Products table and references it by ProductID in an OrderLines table rather than repeating product details in every order line. Which relational design principle does this demonstrate?","options":["Denormalization to speed up writes","Normalization using keys to link related tables","Indexing to enforce permissions","Partitioning to distribute storage"],"correct":[1],"skill":2,"sub":"2.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Splitting data into related tables and linking them with primary/foreign keys, instead of duplicating details, is the core of normalization in a relational design.","source":{"title":"Explore fundamental relational data concepts — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-relational-data-offerings/"}},{"id":"gen-91","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company is migrating an on-premises SQL Server database to Azure. They want a fully managed PaaS service where Microsoft handles patching, backups, and high availability, and they do not need operating-system-level access. Which Azure SQL option best fits?","options":["SQL Server on an Azure Virtual Machine","Azure Database for PostgreSQL","Azure SQL Database","An Azure Storage account with a data lake"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure SQL Database is a fully managed platform-as-a-service (PaaS) offering in which Microsoft manages patching, backups, and high availability, with no access to the underlying OS.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-92","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team needs to lift and shift an existing SQL Server workload to Azure while retaining full control over the operating system and the SQL Server instance, including the ability to install custom software on the host. Which option should they choose?","options":["SQL Server on an Azure Virtual Machine","Azure SQL Database serverless","Azure Database for MySQL","Azure SQL Database elastic pool"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"SQL Server on an Azure Virtual Machine is an IaaS option that gives you full control over the OS and SQL Server instance, making it ideal for lift-and-shift migrations that need OS-level access.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-93","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization wants to move dozens of on-premises SQL Server databases to a PaaS service but requires near 100% compatibility with the on-premises SQL Server engine, including features such as SQL Server Agent, cross-database queries, and CLR. Which Azure SQL option is the best match?","options":["Azure SQL Database single database","Azure SQL Managed Instance","Azure Database for PostgreSQL flexible server","SQL Server on an Azure Virtual Machine"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure SQL Managed Instance is a PaaS option offering near 100% compatibility with the on-premises SQL Server engine, supporting instance-scoped features like SQL Server Agent and cross-database queries.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-94","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement correctly distinguishes IaaS from PaaS among the Azure SQL deployment options?","options":["Azure SQL Database is IaaS, while SQL Server on an Azure VM is PaaS","Azure SQL Managed Instance is IaaS, while SQL Server on an Azure VM is PaaS","All three Azure SQL options are IaaS","SQL Server on an Azure VM is IaaS, while Azure SQL Database and Azure SQL Managed Instance are PaaS"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"SQL Server on an Azure Virtual Machine is infrastructure-as-a-service (IaaS), whereas Azure SQL Database and Azure SQL Managed Instance are platform-as-a-service (PaaS) offerings.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-95","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A development team runs an application on the open-source MySQL database and wants to move it to a fully managed Azure service without changing the database engine. Which Azure service should they use?","options":["Azure SQL Managed Instance","Azure Database for PostgreSQL","Azure Database for MySQL flexible server","Azure Cosmos DB"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Database for MySQL flexible server is a managed PaaS service that runs the community MySQL engine, letting teams migrate MySQL workloads without changing the database engine.","source":{"title":"Azure Database for MySQL flexible server overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/mysql/flexible-server/overview"}},{"id":"gen-96","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company standardizes on PostgreSQL and needs a managed Azure database that supports PostgreSQL extensions such as PostGIS while offloading patching and backups to Microsoft. Which service should they select?","options":["Azure Database for PostgreSQL flexible server","Azure Database for MySQL flexible server","SQL Server on an Azure Virtual Machine","Azure SQL Database"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Database for PostgreSQL flexible server is a managed PaaS service running the community PostgreSQL engine and supports popular extensions such as PostGIS.","source":{"title":"Azure Database for PostgreSQL flexible server overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/postgresql/overview"}},{"id":"gen-97","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An application has an unpredictable, intermittent workload with long idle periods, and the team wants to minimize compute costs by having the database automatically pause when unused and scale compute based on demand. Which Azure SQL Database option best supports this?","options":["A provisioned single database with fixed vCores","Azure SQL Database serverless","SQL Server on an Azure Virtual Machine","Azure SQL Managed Instance"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The serverless compute tier of Azure SQL Database automatically scales compute based on workload demand and can auto-pause during inactive periods, billing only for storage while paused.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-98","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A SaaS provider hosts many small databases, one per customer, with usage that peaks at different times. They want the databases to share a pool of compute resources to optimize cost. Which Azure SQL Database feature should they use?","options":["Serverless auto-pause","SQL Server on an Azure Virtual Machine","Zone-redundant Managed Instance","Elastic pools"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Elastic pools let multiple Azure SQL databases share a common set of resources, which is cost-effective for many databases with varying and unpredictable usage patterns.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-99","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following is NOT part of the Azure SQL family of services?","options":["Azure SQL Database","Azure SQL Managed Instance","SQL Server on Azure Virtual Machines","Azure Database for PostgreSQL"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Azure SQL family consists of Azure SQL Database, Azure SQL Managed Instance, and SQL Server on Azure Virtual Machines. Azure Database for PostgreSQL is an open-source database service, not part of the Azure SQL family.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-100","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants a managed Azure relational database and requires high availability where a standby replica is provisioned in a different availability zone within the same region. Both Azure Database for MySQL and Azure Database for PostgreSQL flexible server can provide this through which capability?","options":["Zone-redundant high availability","Read scale-out only","Geo-restore from Blob storage","Hierarchical namespace"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Both Azure Database for MySQL and PostgreSQL flexible server support zone-redundant high availability, deploying a standby replica in a different availability zone for resilience against zone failures.","source":{"title":"Azure Database for MySQL flexible server overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/mysql/flexible-server/overview"}},{"id":"gen-101","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A cost-conscious startup runs a non-production PostgreSQL database that is only used during business hours. Which capability of Azure Database for PostgreSQL flexible server can help them reduce costs during idle time?","options":["Stopping and starting the server on demand","Enabling a hierarchical namespace","Switching to Azure Table storage","Deploying to an Azure Virtual Machine"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Database for PostgreSQL flexible server lets you stop and start the server on demand, so you can pause the server outside business hours to reduce compute costs.","source":{"title":"Azure Database for PostgreSQL flexible server overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/postgresql/overview"}},{"id":"gen-102","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An administrator is choosing between Azure SQL deployment options and wants to minimize administrative overhead as much as possible while still running a relational database. Ordered from most management responsibility for the customer to least, which sequence is correct?","options":["Azure SQL Database, Azure SQL Managed Instance, SQL Server on Azure VM","SQL Server on Azure VM, Azure SQL Managed Instance, Azure SQL Database","Azure SQL Managed Instance, Azure SQL Database, SQL Server on Azure VM","Azure SQL Database, SQL Server on Azure VM, Azure SQL Managed Instance"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"SQL Server on an Azure VM (IaaS) requires the most customer management, Azure SQL Managed Instance requires less, and Azure SQL Database (PaaS) requires the least because Microsoft handles the most operational tasks.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-103","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"When evaluating relational database services in Azure, which pair correctly represents the managed open-source database offerings currently available?","options":["Azure Database for MySQL and Azure Database for PostgreSQL","Azure Database for MySQL and Azure Cosmos DB","Azure SQL Database and Azure SQL Managed Instance","Azure Database for PostgreSQL and Azure Table storage"],"correct":[0],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure provides managed services for the open-source relational engines MySQL and PostgreSQL as Azure Database for MySQL and Azure Database for PostgreSQL.","source":{"title":"Explore relational database services in Azure — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-provision-deploy-relational-database-offerings-azure/"}},{"id":"gen-104","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retailer already runs its e-commerce platform on MySQL and wants to move to a managed Azure service while keeping application compatibility with the MySQL engine. Which service provides a managed MySQL environment with built-in automated backups and patching?","options":["Azure SQL Database","Azure Database for MySQL flexible server","Azure SQL Managed Instance","SQL Server on an Azure Virtual Machine"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Database for MySQL flexible server is a managed PaaS service that runs the MySQL engine and provides automated backups, patching, and high availability while maintaining application compatibility.","source":{"title":"Azure Database for MySQL flexible server overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/mysql/flexible-server/overview"}},{"id":"gen-105","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A solution architect needs a relational Azure database service that gives fine-grained control over server configuration parameters and maintenance windows for a PostgreSQL workload, while still being a managed PaaS service. Which deployment model of Azure Database for PostgreSQL is designed to provide this flexibility?","options":["Single Server (retired model)","Azure Table storage","Flexible server","SQL Server on an Azure Virtual Machine"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The flexible server deployment model of Azure Database for PostgreSQL is designed to give greater control over database configuration parameters and scheduled maintenance windows while remaining a managed service.","source":{"title":"Azure Database for PostgreSQL flexible server overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/postgresql/overview"}},{"id":"gen-106","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company is comparing Azure SQL options for a new cloud-native application that needs a single relational database with automatic scaling and minimal management. They do not need instance-level features or OS access. Which option is most appropriate?","options":["SQL Server on an Azure Virtual Machine","Azure SQL Managed Instance","Azure SQL Database","Azure Database for MySQL flexible server"],"correct":[2],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure SQL Database is optimized for modern cloud-native applications that need a single managed relational database with minimal administration and does not require instance-scoped features or OS access.","source":{"title":"What is Azure SQL? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/azure-sql/azure-sql-iaas-vs-paas-what-is-overview"}},{"id":"gen-107","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement about Azure Database for MySQL flexible server is correct?","options":["It is part of the Azure SQL family and runs the Microsoft SQL Server engine","It is a managed service for the open-source MySQL database engine","It is an IaaS offering requiring the customer to patch the operating system","It stores only unstructured data as blobs"],"correct":[1],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Database for MySQL flexible server is a managed PaaS service for the open-source MySQL engine; Microsoft handles OS and engine patching, so it is not IaaS and is not part of the Azure SQL family.","source":{"title":"Azure Database for MySQL flexible server overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/mysql/flexible-server/overview"}},{"id":"gen-108","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An enterprise wants to consolidate several relational database engines in Azure. For their SQL Server workloads they will use the Azure SQL family, and for their open-source workloads they need managed services. Which combination correctly maps the open-source engines to Azure services?","options":["MySQL to Azure SQL Database, and PostgreSQL to Azure SQL Managed Instance","MySQL to Azure Cosmos DB, and PostgreSQL to Azure Table storage","MySQL and PostgreSQL both to SQL Server on Azure Virtual Machines","MySQL to Azure Database for MySQL, and PostgreSQL to Azure Database for PostgreSQL"],"correct":[3],"skill":2,"sub":"2.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure provides dedicated managed services that match each open-source engine: Azure Database for MySQL for MySQL workloads and Azure Database for PostgreSQL for PostgreSQL workloads.","source":{"title":"Explore relational database services in Azure — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-provision-deploy-relational-database-offerings-azure/"}},{"id":"gen-109","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company needs to store millions of scanned images, video files, and log documents that do not follow a fixed schema, and wants to serve some of them directly to a web browser over HTTP. Which Azure Storage service is optimized for this kind of massive unstructured object data?","options":["Azure Table storage","Azure Blob Storage","Azure Queue storage","Azure Files"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Blob Storage is optimized for storing massive amounts of unstructured (object) data such as images, video, and documents, and blobs are accessible over HTTP/HTTPS via URL.","source":{"title":"Introduction to Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-110","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A development team wants to lift and shift an on-premises application that reads and writes files on a shared network drive using the SMB protocol, without rewriting the application to call storage APIs. Which Azure Storage service best supports this scenario?","options":["Azure Files","Azure Blob Storage","Azure Table storage","Azure Queue storage"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Files provides fully managed cloud file shares accessible via the industry-standard SMB and NFS protocols, so applications can mount them like a network drive without code changes.","source":{"title":"What is Azure Files — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"}},{"id":"gen-111","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An application must exchange asynchronous messages between a front-end web tier and a back-end worker tier, buffering work items until the workers are ready to process them. Which Azure Storage service is designed to store and retrieve these messages?","options":["Azure Blob Storage","Azure Files","Azure Queue storage","Azure Table storage"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Queue storage provides messaging for storing large numbers of messages that can be accessed asynchronously, decoupling application components such as web and worker tiers.","source":{"title":"Introduction to Azure Queue Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/queues/storage-queues-introduction"}},{"id":"gen-112","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team needs a schemaless NoSQL store for structured, non-relational data where each entity is identified by a partition key and a row key, and different entities in the same table can have different sets of properties. Which Azure Storage service fits this requirement?","options":["Azure Files","Azure Table storage","Azure Queue storage","Azure Blob Storage"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Table storage is a NoSQL key/attribute store for structured, non-relational data; entities are identified by a partition key and row key and are not required to share the same properties.","source":{"title":"Azure Table storage overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"}},{"id":"gen-113","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A big-data analytics team wants to organize files in the storage account into a true directory hierarchy so operations like renaming or deleting a folder are single atomic actions, and to run analytics engines over Parquet and CSV files. Which capability should they enable?","options":["Azure Queue storage","Azure Files SMB shares","Azure Data Lake Storage (hierarchical namespace)","Azure Table storage"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Data Lake Storage Gen2 adds a hierarchical namespace on top of Blob Storage, organizing objects into a hierarchy of directories for efficient big-data analytics operations.","source":{"title":"Introduction to Azure Data Lake Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction"}},{"id":"gen-114","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Blob storage supports three types of blobs. Which blob type is optimized for storing files that are read and written in large blocks, such as text and binary documents, images, and video?","options":["Page blobs","Append blobs","Block blobs","Table blobs"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Block blobs store text and binary data in blocks and are ideal for files like documents, images, and media that are uploaded and read as a whole.","source":{"title":"Introduction to Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-115","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A logging application must repeatedly add new entries to the end of a file without modifying data already written. Which type of blob is optimized for this append-only pattern?","options":["Append blob","Block blob","Page blob","Queue blob"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Append blobs are made up of blocks optimized for append operations, making them ideal for scenarios such as logging where data is continuously added to the end of the blob.","source":{"title":"Introduction to Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-116","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company stores blob data that is accessed frequently in the first month, then rarely after that, and finally must be retained for years for compliance while almost never being read. To minimize storage cost, which Blob Storage feature should they use to match cost to usage?","options":["Blob soft delete","Access tiers (Hot, Cool, Cold, Archive)","Hierarchical namespace","Shared access signatures"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Blob Storage access tiers (Hot, Cool, Cold, and Archive) let you place data in the tier whose storage and access costs match how frequently the data is used, lowering overall cost.","source":{"title":"Introduction to Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-117","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which Blob Storage access tier offers the lowest storage cost but the highest access cost and latency, and is intended for data that is rarely accessed and can tolerate several hours of retrieval time?","options":["Hot tier","Cool tier","Archive tier","Cold tier"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Archive tier has the lowest storage cost and highest access cost; it is an offline tier for rarely accessed data, and blobs must be rehydrated before they can be read, which can take hours.","source":{"title":"Introduction to Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-118","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"For data that is accessed and modified very frequently, such as an active website's content, which Blob Storage access tier is the most appropriate default choice?","options":["Hot tier","Cool tier","Cold tier","Archive tier"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Hot tier has the highest storage cost but the lowest access cost, making it the right choice for frequently accessed and frequently modified data.","source":{"title":"Introduction to Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-119","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Within the Azure Blob Storage object model, in what unit are blobs organized inside a storage account, similar to a directory that groups related blobs?","options":["Tables","Containers","Shares","Queues"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In Blob Storage, a storage account contains containers, and each container organizes a set of blobs, similar to how a directory groups files.","source":{"title":"Introduction to Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-120","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Two separate applications running on different Azure virtual machines both need concurrent read/write access to the same set of configuration files through a mounted share. Which Azure Storage service is designed to be shared by multiple clients simultaneously in this way?","options":["Azure Table storage","Azure Queue storage","Azure Files","Azure Blob Storage"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Files shares can be mounted concurrently by cloud or on-premises deployments, allowing multiple clients (such as VMs) to access the same files at the same time.","source":{"title":"What is Azure Files — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"}},{"id":"gen-121","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retailer wants to store product catalog entities where most items have a common set of attributes but some items add extra optional attributes, and they need very fast key-based lookups at low cost without SQL joins. Which Azure Storage service is best suited?","options":["Azure Table storage","Azure Blob Storage","Azure Files","Azure SQL Database"],"correct":[0],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Table storage is a schemaless NoSQL key/attribute store designed for fast, inexpensive access to structured, non-relational data using partition and row keys rather than relational joins.","source":{"title":"Azure Table storage overview — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/tables/table-storage-overview"}},{"id":"gen-122","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Azure Files supports two main protocols for accessing file shares. Besides SMB, which protocol can Azure Files shares also be created with to support Linux and macOS workloads?","options":["FTP","NFS","HTTP","AMQP"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Files supports file shares over the SMB protocol and the NFS protocol, the latter being commonly used by Linux and macOS clients.","source":{"title":"What is Azure Files — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"}},{"id":"gen-123","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"What is the approximate maximum size of a single message that can be stored in an Azure Queue storage queue?","options":["64 KB","256 KB","4 MB","1 MB"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An individual message in Azure Queue storage can be up to 64 KB in size, and a queue can contain millions of messages up to the total capacity limit of the storage account. The correct maximum is 64 KB.","source":{"title":"Introduction to Azure Queue Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/queues/storage-queues-introduction"}},{"id":"gen-124","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data engineering team is building a data lake for analytics and wants file-system semantics and directory-level security (POSIX-style ACLs) on their object storage. Which Azure Storage capability provides this?","options":["Azure Queue storage","Azure Data Lake Storage Gen2","Azure Table storage","Azure Files REST API"],"correct":[1],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Data Lake Storage Gen2 builds on Blob Storage and adds a hierarchical namespace with file-system semantics and directory- and file-level ACLs, which are ideal for big-data analytics.","source":{"title":"Introduction to Azure Data Lake Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction"}},{"id":"gen-125","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A solution needs to store data that is accessed infrequently and stored for at least 30 days, but that must remain online and available for immediate read access when occasionally needed. Which Blob Storage access tier best balances cost and availability for this data?","options":["Archive tier","Hot tier","Cool tier","Premium tier"],"correct":[2],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Cool tier is optimized for data that is infrequently accessed and stored for a minimum of 30 days while remaining online for immediate access, offering lower storage cost than Hot.","source":{"title":"Introduction to Blob Storage — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/blobs/storage-blobs-introduction"}},{"id":"gen-126","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization wants to migrate an on-premises file server to Azure and keep frequently accessed files cached on local servers while the authoritative copy lives in the cloud. Which Azure Storage service, together with Azure File Sync, enables this hybrid approach?","options":["Azure Blob Storage","Azure Table storage","Azure Queue storage","Azure Files"],"correct":[3],"skill":3,"sub":"3.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Files can be used with Azure File Sync to cache Azure file shares on on-premises Windows Servers, centralizing file storage in the cloud while keeping fast local access.","source":{"title":"What is Azure Files — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/storage/files/storage-files-introduction"}},{"id":"gen-127","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retail company needs a globally distributed database that can serve millions of users worldwide with single-digit millisecond read latency, and automatically replicate data to Azure regions close to each customer. Which Azure service is designed for this?","options":["Azure SQL Managed Instance","Azure Cosmos DB","Azure Blob Storage","Azure Database for PostgreSQL flexible server"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Cosmos DB is a globally distributed, multi-model NoSQL database that offers turnkey global distribution and single-digit-millisecond response times by replicating data to regions near users.","source":{"title":"Welcome to Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/overview"}},{"id":"gen-128","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A development team is migrating an existing MongoDB application to Azure and wants to reuse their current MongoDB drivers and tools with minimal code changes. Which Azure Cosmos DB API should they choose?","options":["API for MongoDB","API for Table","API for Apache Gremlin","API for Apache Cassandra"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Azure Cosmos DB API for MongoDB supports the MongoDB wire protocol, so existing MongoDB drivers, SDKs, and tools continue to work with little or no code change.","source":{"title":"Welcome to Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/overview"}},{"id":"gen-129","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An application stores highly connected data such as a social network of people, their friendships, and shared interests, and needs to traverse relationships between entities efficiently. Which Azure Cosmos DB API is best suited for this graph-based data?","options":["API for NoSQL","API for Table","API for Apache Gremlin","API for MongoDB"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Azure Cosmos DB API for Apache Gremlin is a graph database API used to store and query graph data made up of vertices (entities) and edges (relationships).","source":{"title":"Explore fundamentals of Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-non-relational-data-stores-azure/"}},{"id":"gen-130","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which Azure Cosmos DB API is the native, recommended API for new applications and stores data as JSON documents that can be queried using a SQL-like query language?","options":["API for Apache Cassandra","API for Table","API for MongoDB","API for NoSQL"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The API for NoSQL is Azure Cosmos DB's native API, storing data in JSON document format and supporting a SQL-like syntax for querying; it receives new features first.","source":{"title":"Welcome to Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/overview"}},{"id":"gen-131","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An IoT solution ingests a continuous, high-volume stream of telemetry from thousands of connected vehicles and must write and read this data at massive scale with low latency. Why is Azure Cosmos DB a strong fit for this scenario?","options":["It enforces a fixed relational schema that validates every telemetry record on write","It is optimized to handle high-throughput ingestion and low-latency access to large volumes of rapidly changing data","It is designed primarily for long-term cold archival of infrequently accessed files","It only supports batch loading of data once per day"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"IoT and telematics are a common Cosmos DB use case because it can ingest high volumes of device data at speed and provide low-latency access for real-time processing and analytics.","source":{"title":"Common Azure Cosmos DB use cases — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/use-cases"}},{"id":"gen-132","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team already runs applications built on Apache Cassandra using Cassandra Query Language (CQL) and wants a fully managed cloud service that supports their existing CQL-based code. Which Azure Cosmos DB API should they select?","options":["API for Apache Cassandra","API for NoSQL","API for Apache Gremlin","API for Table"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Azure Cosmos DB API for Apache Cassandra is a column-family store compatible with Cassandra Query Language, letting existing Cassandra applications run against a fully managed service.","source":{"title":"Explore fundamentals of Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-non-relational-data-stores-azure/"}},{"id":"gen-133","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An existing application uses Azure Table Storage with key-value pairs, and the team wants to move to a premium service offering global distribution, guaranteed low latency, and dedicated throughput while keeping their key-value data model. Which Azure Cosmos DB API is the natural upgrade path?","options":["API for MongoDB","API for Apache Gremlin","API for Table","API for Apache Cassandra"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Azure Cosmos DB API for Table is a key-value store that works with existing Azure Table Storage applications while adding global distribution, low latency, and higher throughput.","source":{"title":"Explore fundamentals of Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-non-relational-data-stores-azure/"}},{"id":"gen-134","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes the type of database that Azure Cosmos DB is?","options":["A relational data warehouse optimized for complex analytical star-schema queries","A message queue service used to decouple application components","An in-memory cache used only to speed up an existing relational database","A fully managed NoSQL and relational database for modern app development, supporting multiple data models and APIs"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Cosmos DB is a fully managed NoSQL (and relational, via the API for PostgreSQL) database that supports several data models and APIs for building modern, scalable applications.","source":{"title":"Welcome to Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/overview"}},{"id":"gen-135","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A gaming company launches a new mobile game that may suddenly go viral, requiring the backend database to scale instantly to handle unpredictable spikes in players while keeping latency low. Which capability of Azure Cosmos DB addresses this need?","options":["Elastic scalability of throughput and storage to handle unpredictable, spiky workloads","A requirement to manually pre-provision fixed-size servers weeks in advance","Automatic conversion of all game data into a normalized relational schema","Read-only access that prevents any writes during peak traffic"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Gaming is a classic Cosmos DB use case because it can elastically scale throughput and storage to absorb sudden, unpredictable traffic spikes while maintaining low latency for a good player experience.","source":{"title":"Common Azure Cosmos DB use cases — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/use-cases"}},{"id":"gen-136","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Azure Cosmos DB, how is data organized within a database?","options":["Data is stored only as flat files in a single blob container","Data is stored in items that are grouped into containers within a database","Data must be stored exclusively in normalized relational tables with foreign keys","Data is stored as rows in a single fixed table per account"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In Azure Cosmos DB, an account contains databases, each database holds containers, and each container stores items (such as JSON documents), providing a flexible schema-agnostic structure.","source":{"title":"Welcome to Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/overview"}},{"id":"gen-137","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An e-commerce site needs to store a product catalog where different products have very different attributes (for example, books have authors and page counts while clothing has sizes and colors). Why is Azure Cosmos DB well suited to a retail catalog like this?","options":["It requires every product to share an identical set of columns defined up front","It can only store text and cannot represent nested product attributes","Its schema-agnostic document model can flexibly store items with varying structures and serve them with low latency","It forces all catalog data to be exported to a data warehouse before it can be read"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Retail and marketing catalogs are a common Cosmos DB use case because its flexible, schema-agnostic JSON document model stores items with varying attributes and serves them quickly at scale.","source":{"title":"Common Azure Cosmos DB use cases — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/use-cases"}},{"id":"gen-138","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which Azure Cosmos DB feature lets an administrator add or remove Azure regions associated with a database account at any time to bring data closer to users and improve availability?","options":["Manual nightly export and re-import between regions","Turnkey global distribution across any number of Azure regions","A single-region-only deployment that cannot be changed after creation","Storing data only in the primary region with no replication option"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Cosmos DB provides turnkey global distribution, allowing you to add or remove any number of Azure regions to your account at any time to reduce latency and increase availability.","source":{"title":"Welcome to Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/overview"}},{"id":"gen-139","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A social media platform must store user profiles, posts, and activity feeds while serving a rapidly growing global user base with fast, responsive reads and writes. Which combination of Azure Cosmos DB characteristics makes it a good fit for such web and mobile applications?","options":["Single-region deployment and batch-only processing","Fixed relational schema and hourly refresh windows","Cold-tier archival storage with high retrieval latency","Low latency, elastic scalability, and global distribution for responsive user experiences"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Web, mobile, and social applications are a common Cosmos DB use case because it delivers low-latency access, elastic scale, and global distribution to keep user experiences fast as the audience grows.","source":{"title":"Common Azure Cosmos DB use cases — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/use-cases"}},{"id":"gen-140","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants the familiarity of a relational, distributed PostgreSQL database managed within Azure Cosmos DB for a new application. Which Azure Cosmos DB API supports this?","options":["API for PostgreSQL","API for Apache Gremlin","API for Table","API for MongoDB"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Cosmos DB for PostgreSQL is a managed, distributed relational (PostgreSQL) offering, showing that Cosmos DB supports both NoSQL and relational data models through its API choices.","source":{"title":"Welcome to Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/overview"}},{"id":"gen-141","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Azure Cosmos DB is often described as a multi-model database. What does this mean when selecting an API for a new project?","options":["You must use every available API at the same time within one container","You choose one API that matches your data model and application needs, such as document, key-value, column-family, or graph","It can only ever store data in JSON document format regardless of API","The API automatically changes on its own based on query load"],"correct":[1],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"As a multi-model service, Azure Cosmos DB lets you pick the API that fits your workload — document (NoSQL/MongoDB), key-value (Table), column-family (Cassandra), or graph (Gremlin).","source":{"title":"Explore fundamentals of Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-non-relational-data-stores-azure/"}},{"id":"gen-142","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retailer wants to build a real-time product recommendation and personalization engine that reacts to each shopper's behavior with very low latency. Which Azure Cosmos DB use case does this represent?","options":["Long-term regulatory archival of static records","Nightly batch reporting for a finance department","Personalization, where low-latency access to user data powers real-time recommendations","Hosting static website images and stylesheets"],"correct":[2],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Personalization is a common Cosmos DB use case: its low-latency, globally distributed reads and writes let applications tailor content and recommendations to each user in real time.","source":{"title":"Common Azure Cosmos DB use cases — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/use-cases"}},{"id":"gen-143","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following is a key benefit that Azure Cosmos DB provides as a fully managed service?","options":["Customers must patch and back up the underlying database servers themselves","It guarantees a fixed relational schema is enforced on all incoming data","It can only be accessed from within a single virtual machine","Automatic management, including maintenance, updates, and backups, so teams focus on the application rather than infrastructure"],"correct":[3],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Cosmos DB is fully managed, handling administration such as maintenance, updates, and automatic backups, letting developers concentrate on building applications instead of managing infrastructure.","source":{"title":"Welcome to Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/cosmos-db/overview"}},{"id":"gen-144","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A solution architect must recommend a data store for a new application that expects unpredictable global growth, needs flexible (non-relational) data structures, and requires guaranteed low-latency reads and writes worldwide. Which Azure service best meets all of these requirements?","options":["Azure Cosmos DB","Azure Files","Azure SQL Database single database","Azure Queue Storage"],"correct":[0],"skill":3,"sub":"3.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Cosmos DB combines a flexible NoSQL model, elastic global scalability, and guaranteed single-digit-millisecond latency, making it the right choice for globally distributed, non-relational applications.","source":{"title":"Explore fundamentals of Azure Cosmos DB — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-non-relational-data-stores-azure/"}},{"id":"gen-145","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retail company wants a central relational store that consolidates data from several operational systems and is optimized for read-heavy reporting and historical analysis rather than day-to-day transactions. Which element of a large-scale analytics solution should they build?","options":["An OLTP database","A data warehouse","A message queue","A key-value cache"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A data warehouse is a relational store optimized for analytical (OLAP) queries over consolidated, historical data, typically organized in a star or snowflake schema for reporting.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-146","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data engineer loads raw data into an analytical store first and then runs transformations inside that store using its compute engine. Which data-loading pattern does this describe?","options":["ETL (extract, transform, load)","OLTP","ELT (extract, load, transform)","Normalization"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In ELT, data is extracted and loaded into the target store before transformation, so the transformation work uses the scalable compute of the destination system rather than a separate transformation engine.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-147","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization needs a low-cost, highly scalable location to store large volumes of raw files in many formats (CSV, JSON, Parquet, images) before deciding how they will be processed. Which analytics element best fits this need?","options":["A data lake","A relational data warehouse","An OLTP transactional database","A stored procedure"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A data lake provides scalable, low-cost storage for large volumes of raw data in a wide variety of file formats, without requiring a fixed schema before the data is ingested.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-148","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes a lakehouse?","options":["A message-queuing service for decoupling application components","An architecture that combines the flexible, low-cost storage of a data lake with the structured querying and management features of a data warehouse","A purely in-memory cache used only for transactional workloads","A tool that only visualizes data and cannot store it"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A lakehouse blends the scalable, flexible file storage of a data lake with data-warehouse-style structure, schema, and SQL querying, giving one platform for both raw and modeled analytical data.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-149","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants a single Azure analytics service that provides both SQL-based and Apache Spark-based processing over data in a data lake, along with data integration pipelines. Which service should they choose?","options":["Azure Cosmos DB","Azure Blob Storage","Azure Synapse Analytics","Azure Queue Storage"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Synapse Analytics unifies SQL and Apache Spark engines together with integration pipelines, enabling analytics over data stored in a data lake from one workspace.","source":{"title":"What is Azure Synapse Analytics? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/synapse-analytics/overview-what-is"}},{"id":"gen-150","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"How is Microsoft Fabric best described?","options":["An end-to-end SaaS analytics platform that unifies data movement, lakehouse, warehouse, and business intelligence workloads","An on-premises-only relational database engine","A single-purpose service that can only run streaming queries","A physical storage appliance installed in a customer datacenter"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Microsoft Fabric is a unified software-as-a-service analytics platform that brings together data engineering, data warehousing, data science, real-time, and BI workloads on a single foundation.","source":{"title":"What is Microsoft Fabric? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/microsoft-fabric-overview"}},{"id":"gen-151","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Microsoft Fabric, what is OneLake?","options":["A separate billing portal for Azure subscriptions","A message broker for real-time events","The single, unified, logical data lake automatically provided for all data in a Fabric tenant","A desktop application for building reports"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"OneLake is the single, tenant-wide logical data lake built into Microsoft Fabric, giving all workloads one place to store and access data without moving or duplicating it.","source":{"title":"What is Microsoft Fabric? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/microsoft-fabric-overview"}},{"id":"gen-152","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data engineer needs a cloud service to orchestrate and automate the ingestion and movement of data from many sources into an analytical store, building ETL and ELT pipelines. Which Azure service is designed for this?","options":["Azure Data Factory","Azure Table Storage","Power BI Desktop","Azure Files"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Data Factory is a cloud-based data integration service used to create pipelines that ingest, move, and transform data as ETL or ELT workflows across many sources and destinations.","source":{"title":"Introduction to Azure Data Factory — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/data-factory/introduction"}},{"id":"gen-153","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which description best matches Azure Databricks?","options":["A managed message queue for application integration","A NoSQL document database with multiple APIs","A key-value store for caching web sessions","An Apache Spark-based analytics platform for data engineering, data science, machine learning, and SQL analytics on a lakehouse"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Databricks is a Spark-based platform that supports ETL, data science, machine learning, and SQL analytics using a lakehouse architecture.","source":{"title":"What is Azure Databricks? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/databricks/introduction/"}},{"id":"gen-154","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a modern data warehouse pipeline, what is the primary purpose of the data ingestion stage?","options":["To render interactive dashboards for business users","To capture and load data from various source systems into the analytics environment","To enforce row-level security on reports","To back up virtual machines used by the application tier"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Data ingestion is the step that captures data from source systems and brings it into the data lake or warehouse so it can be processed and analyzed downstream.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-155","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company already stores raw data in a data lake and wants to keep the transformation logic close to that low-cost storage and its scalable compute, rather than transforming data on a separate server before loading. Which approach aligns with this goal?","options":["ELT, because data is loaded into the store first and transformed there","ETL, because data must be fully transformed before it is loaded","Normalization, because it removes all redundancy first","OLTP, because it processes one transaction at a time"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"ELT loads data into the target store first and performs transformations there, taking advantage of the destination's scalable compute — a common pattern for data-lake-based analytics.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-156","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which pair of processing engines does Azure Synapse Analytics provide for working with data in the data lake?","options":["SMTP and FTP","SQL and Apache Spark","Redis and Memcached","Kafka and RabbitMQ"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Synapse Analytics offers both a SQL engine (serverless and dedicated pools) and an Apache Spark engine within the same workspace for analytics over lake data.","source":{"title":"What is Azure Synapse Analytics? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/synapse-analytics/overview-what-is"}},{"id":"gen-157","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization wants a unified analytics solution where business users can also build Power BI reports directly on the same platform that handles data engineering and warehousing, without integrating separate products. Which platform is designed to deliver this?","options":["Azure Queue Storage","Azure Database for MySQL","Microsoft Fabric","Azure Table Storage"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Microsoft Fabric is a single SaaS platform that includes Power BI alongside data engineering, warehousing, data science, and real-time workloads, all built on OneLake.","source":{"title":"What is Microsoft Fabric? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/microsoft-fabric-overview"}},{"id":"gen-158","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which file format is a column-oriented format commonly used for storing large analytical datasets efficiently in a data lake?","options":["Parquet","DOCX","MP3","EXE"],"correct":[0],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Parquet is a compressed, column-oriented file format widely used in data lakes because it is efficient for large-scale analytical queries.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-159","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In an ETL process, what happens during the transform step?","options":["The pipeline permanently deletes all source records","The data is cleaned, reshaped, or aggregated into a structure suited for analysis before it is loaded","The data is encrypted and archived to tape","The reports are published to end users"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In ETL, the transform step applies cleansing, reshaping, and aggregation so the data conforms to the target schema before it is loaded into the analytical store.","source":{"title":"Introduction to Azure Data Factory — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/data-factory/introduction"}},{"id":"gen-160","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data engineering team wants to run large-scale Apache Spark workloads for machine learning and collaborative notebooks on a lakehouse in Azure. Which service is purpose-built for this?","options":["Azure Files","Azure Blob Storage","Azure Cosmos DB","Azure Databricks"],"correct":[3],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Databricks is built around Apache Spark and supports collaborative notebooks, machine learning, and large-scale data engineering on a lakehouse architecture.","source":{"title":"What is Azure Databricks? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/databricks/introduction/"}},{"id":"gen-161","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Compared with a data warehouse, what is a key characteristic of a data lake?","options":["It requires all data to be fully structured and modeled before storage","It can only store a few gigabytes of data","It can store raw data of many types and formats without requiring a predefined schema","It is used exclusively for real-time transaction processing"],"correct":[2],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A data lake stores raw data of diverse types and formats at scale without demanding a fixed schema up front, whereas a data warehouse stores structured, modeled data.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-162","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which sequence correctly represents the typical stages of a modern data warehousing (large-scale analytics) pipeline?","options":["Visualize, then ingest, then store, then delete","Ingest data, store it in a data lake or warehouse, process/transform it, then serve it for analysis and reporting","Encrypt, back up, restore, then archive","Cache, queue, dequeue, then discard"],"correct":[1],"skill":4,"sub":"4.1","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A modern analytics pipeline ingests data from sources, stores it in a lake or warehouse, processes and transforms it, and then serves it to reporting and visualization tools for analysis.","source":{"title":"Explore fundamentals of large-scale analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/examine-components-of-modern-data-warehouse/"}},{"id":"gen-163","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retailer collects sales transactions all day and runs a single job overnight that processes the entire day's file at once to update reports. Which type of data processing does this describe?","options":["Stream processing","Transactional processing","Interactive query processing","Batch processing"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In batch processing, data is collected and stored, then processed together as a group (a batch) on a schedule, such as an overnight run over the whole day's data.","source":{"title":"Explore fundamentals of real-time analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-stream-processing/"}},{"id":"gen-164","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which characteristic best distinguishes stream processing from batch processing?","options":["It always processes larger volumes of data","It can only run once per day on a fixed schedule","It processes each data element continuously as it arrives, with very low latency","It requires all data to be collected before any processing begins"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Stream processing acts on each piece of data (or small windows of data) in real time as it is generated, producing results with very low latency, unlike batch processing which waits for a full set of data.","source":{"title":"Explore fundamentals of real-time analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-stream-processing/"}},{"id":"gen-165","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A logistics company needs to detect abnormal temperature readings from thousands of refrigerated trucks and raise alerts within seconds. Which processing approach fits this requirement?","options":["Batch processing on a nightly schedule","Stream (real-time) processing","Manual periodic report generation","Weekly extract-transform-load jobs"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Detecting conditions and raising alerts within seconds of data being generated is a real-time scenario, which requires stream processing rather than scheduled batch jobs.","source":{"title":"Explore fundamentals of real-time analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-stream-processing/"}},{"id":"gen-166","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement about latency is generally true when comparing batch and streaming solutions?","options":["Batch processing typically has lower latency than streaming","Streaming and batch always have identical latency","Streaming typically has lower latency than batch processing","Latency is not a relevant consideration for either approach"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Streaming solutions process data as it arrives and typically deliver results with much lower latency than batch solutions, which introduce delay by waiting to collect and process data in groups.","source":{"title":"Explore fundamentals of real-time analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-stream-processing/"}},{"id":"gen-167","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In a real-time analytics architecture, what is the role of a source such as Azure Event Hubs or Azure IoT Hub?","options":["To visualize the processed results in dashboards","To capture and ingest the stream of events as they are generated","To permanently archive results in a relational data warehouse","To train machine learning models on historical data"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In a streaming architecture, an ingestion source such as Event Hubs or IoT Hub captures the perpetual stream of events so a processing engine can consume and act on them.","source":{"title":"What is Azure Event Hubs? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/event-hubs/event-hubs-about"}},{"id":"gen-168","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which Azure service is a fully managed, real-time event ingestion service designed to receive and buffer millions of events per second from many producers?","options":["Azure Blob Storage","Azure SQL Database","Azure Event Hubs","Azure Files"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Event Hubs is a big-data streaming platform and event ingestion service that can receive and process millions of events per second from multiple producers.","source":{"title":"What is Azure Event Hubs? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/event-hubs/event-hubs-about"}},{"id":"gen-169","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization has existing applications built with Apache Kafka producers and consumers and wants to move ingestion to Azure without rewriting that code. Which capability of Azure Event Hubs helps?","options":["A built-in Power BI report designer","Automatic conversion of events into relational tables","Native SMB file share support","Kafka protocol compatibility (an Apache Kafka endpoint)"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Event Hubs provides an Apache Kafka-compatible endpoint, so existing Kafka client applications can send and receive events with Event Hubs without changing their code.","source":{"title":"What is Azure Event Hubs? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/event-hubs/event-hubs-about"}},{"id":"gen-170","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which Azure service is a managed engine that runs perpetual queries over streaming data using a SQL-like query language?","options":["Azure Data Factory","Azure Stream Analytics","Azure Table Storage","Azure Cosmos DB"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Stream Analytics is a real-time analytics service that runs perpetual SQL-based queries against streaming data from inputs such as Event Hubs and IoT Hub.","source":{"title":"Introduction to Azure Stream Analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/stream-analytics/stream-analytics-introduction"}},{"id":"gen-171","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A typical Azure Stream Analytics job is defined by three main parts. Which set correctly describes them?","options":["Tables, views, and stored procedures","A cluster, a notebook, and a job schedule","One or more inputs, a query, and one or more outputs","A source, a sink, and a firewall rule"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An Azure Stream Analytics job ingests data from one or more inputs, transforms it with a SQL-like query, and writes results to one or more outputs.","source":{"title":"Introduction to Azure Stream Analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/stream-analytics/stream-analytics-introduction"}},{"id":"gen-172","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following is a valid output destination for an Azure Stream Analytics job so results can be stored or visualized?","options":["A physical on-premises tape drive only","The Windows registry","An email inbox only","Azure Blob Storage, Azure SQL Database, or Power BI"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Stream Analytics can write query results to outputs such as Azure Blob Storage, Azure SQL Database, Azure Synapse Analytics, and Power BI for storage or real-time visualization.","source":{"title":"Introduction to Azure Stream Analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/stream-analytics/stream-analytics-introduction"}},{"id":"gen-173","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Why is Azure Stream Analytics often described as an appealing choice for teams without deep streaming-code expertise?","options":["It requires writing custom C++ streaming operators","It uses a familiar SQL-based query language and is a fully managed service","It only runs on a self-managed Kubernetes cluster","It cannot connect to Event Hubs or IoT Hub"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Stream Analytics is a fully managed PaaS service that lets you define stream processing with a familiar SQL-like query language, avoiding the need to write low-level streaming code.","source":{"title":"Introduction to Azure Stream Analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/azure/stream-analytics/stream-analytics-introduction"}},{"id":"gen-174","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data engineer uses Apache Spark to process an unbounded stream of data using the same DataFrame API used for batch jobs. Which technology is being used?","options":["Azure Table Storage","T-SQL stored procedures","Spark Structured Streaming","Azure Files snapshots"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Spark Structured Streaming lets you process real-time streaming data using the same Spark DataFrame/SQL API used for batch data, treating the stream as an unbounded table.","source":{"title":"Explore fundamentals of real-time analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-stream-processing/"}},{"id":"gen-175","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Azure, which services provide Apache Spark pools that can run Spark Structured Streaming workloads?","options":["Azure Files and Azure Queue Storage","Azure DNS and Azure Traffic Manager","Azure Synapse Analytics and Azure Databricks","Azure Key Vault and Azure Monitor"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Azure Synapse Analytics and Azure Databricks both provide managed Apache Spark pools that can run Spark Structured Streaming to process real-time data.","source":{"title":"Explore fundamentals of real-time analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-stream-processing/"}},{"id":"gen-176","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which Microsoft Fabric experience is purpose-built for ingesting, analyzing, and acting on high-volume streaming and time-series data?","options":["Data Warehouse","Power BI paginated reports","Data Factory pipelines","Real-Time Intelligence"],"correct":[3],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Real-Time Intelligence in Microsoft Fabric is the workload designed for ingesting, processing, querying, and acting on streaming and time-series data.","source":{"title":"Real-Time Intelligence in Microsoft Fabric — Microsoft Learn","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/overview"}},{"id":"gen-177","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Within Fabric Real-Time Intelligence, which component is used to capture and transform streams of events and route them to destinations with a low-code experience?","options":["Eventstream","Dataflow Gen1","A relational stored procedure","A Power BI slicer"],"correct":[0],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Eventstreams in Fabric Real-Time Intelligence let you capture, transform, and route real-time events to various destinations, such as an eventhouse, using a no-code/low-code editor.","source":{"title":"Real-Time Intelligence in Microsoft Fabric — Microsoft Learn","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/overview"}},{"id":"gen-178","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In Fabric Real-Time Intelligence, where is streaming data typically stored so it can be queried with Kusto Query Language (KQL)?","options":["An Azure Files share","An eventhouse (KQL database)","A Cosmos DB graph container","A Power BI dashboard tile"],"correct":[1],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"An eventhouse, containing one or more KQL databases, is the analytics store in Fabric Real-Time Intelligence optimized for large volumes of time-series data queried with KQL.","source":{"title":"Real-Time Intelligence in Microsoft Fabric — Microsoft Learn","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/overview"}},{"id":"gen-179","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A team wants a central place in Microsoft Fabric to discover, ingest, and connect to streaming data sources across the organization. Which feature provides this?","options":["The Power BI Q&A visual","The OneLake file explorer only","The Real-Time hub","A SQL Server Agent job"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The Real-Time hub is the central catalog in Fabric Real-Time Intelligence for discovering, ingesting, and connecting to streaming data sources from across the organization.","source":{"title":"Real-Time Intelligence in Microsoft Fabric — Microsoft Learn","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/overview"}},{"id":"gen-180","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which scenario is the best candidate for batch processing rather than stream processing?","options":["Raising an alert the moment a sensor exceeds a threshold","Updating a live dashboard as each click occurs on a website","Generating monthly billing statements from a full month of usage records","Detecting fraudulent card transactions in real time"],"correct":[2],"skill":4,"sub":"4.2","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Generating monthly statements from a complete set of records is well suited to scheduled batch processing, whereas the other scenarios require low-latency real-time stream processing.","source":{"title":"Explore fundamentals of real-time analytics — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-stream-processing/"}},{"id":"gen-181","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A retail analyst needs to build interactive reports and publish them so colleagues can view dashboards in a browser and on mobile devices. Which combination of Power BI components fits this workflow?","options":["Power BI Desktop to author reports, and the Power BI service to publish and share them online","Power BI Desktop only, with reports emailed as PDF attachments","The Power BI service only, because Desktop cannot create reports","Azure Data Studio to author reports, and OneDrive to share them"],"correct":[0],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The typical Power BI workflow authors reports in Power BI Desktop, then publishes them to the Power BI service where they can be shared, viewed in a browser, and consumed on the Power BI mobile app.","source":{"title":"What is Power BI? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/fundamentals/power-bi-overview"}},{"id":"gen-182","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data analyst wants to compare monthly sales across four product categories to see which category contributes the most in each month. Which visualization is most appropriate?","options":["A map visualization","A single KPI card","A clustered or stacked column/bar chart","A gauge visualization"],"correct":[2],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Bar and column charts are designed to compare values across categories, making them ideal for comparing sales among product categories across months.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-183","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Power BI workflow, what is the primary purpose of building a data model after importing data into Power BI Desktop?","options":["To physically move the source data into Azure Blob Storage","To define relationships between tables and create measures so visuals can aggregate data correctly","To convert all reports into static PDF documents","To replace the need for any data source connections"],"correct":[1],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The data model defines tables, the relationships between them, and calculated measures, enabling report visuals to slice and aggregate data consistently across the report.","source":{"title":"Explore fundamentals of data visualization — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-data-visualization/"}},{"id":"gen-184","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An analyst needs to show a single summarized value, such as total revenue for the current year, prominently at the top of a report page. Which visual is best suited?","options":["A card visualization","A scatter chart","A treemap","A line chart"],"correct":[0],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A card displays a single number such as a total or key metric, making it ideal for highlighting one important summarized value.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-185","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A business wants to visualize a trend of website visits over the past 12 months to identify seasonality. Which visualization best emphasizes change over a continuous time period?","options":["A pie chart","A matrix","A line chart","A slicer"],"correct":[2],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Line charts are ideal for showing trends and changes in values over a continuous interval such as time, making seasonality easy to spot.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-186","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which statement best describes the relationship between Power BI Desktop and the Power BI service?","options":["Power BI Desktop is a paid mobile app while the service is a desktop program","Power BI Desktop is used mainly to author reports and models, while the service is an online platform for publishing, sharing, and collaboration","Both are identical and interchangeable in every capability","The Power BI service is used to author reports and Desktop is used only to view them"],"correct":[1],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power BI Desktop is a Windows application focused on data connection, modeling, and report authoring, whereas the Power BI service is a cloud platform for publishing, sharing, and collaborating on reports and dashboards.","source":{"title":"What is Power BI? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/fundamentals/power-bi-overview"}},{"id":"gen-187","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An analyst wants to let report viewers filter all visuals on a page by selecting a specific region from a list. Which Power BI element should they add?","options":["A gauge","A KPI visual","A slicer","A scatter chart"],"correct":[2],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A slicer is an on-canvas filter that lets report consumers interactively narrow the data shown across the other visuals on the page.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-188","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A company wants to display detailed sales figures broken down by product rows and quarter columns, with subtotals, similar to a PivotTable. Which visualization is most appropriate?","options":["A matrix visualization","A single card","A funnel chart","A map"],"correct":[0],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A matrix supports a stepped, cross-tabulated layout with rows, columns, and subtotals, making it well suited to detailed grid-style breakdowns.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-189","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An organization needs to show sales totals by country on a geographic display so viewers can quickly see which regions perform best. Which visualization is the best fit?","options":["A ribbon chart","A map visualization","A table","A gauge"],"correct":[1],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Map visualizations plot data by geographic location, making them ideal for comparing values such as sales across countries or regions.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-190","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A sales manager wants to track a single metric against a target, showing progress toward a goal on a report. Which visualization is designed for this purpose?","options":["A scatter chart","A stacked area chart","A treemap","A gauge or KPI visualization"],"correct":[3],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Gauge and KPI visuals are built to show a measure relative to a target or goal, communicating progress at a glance.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-191","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Before creating any visuals in Power BI Desktop, what is typically the first step in the data visualization workflow?","options":["Publishing an empty report to the Power BI service","Connecting to and importing data from one or more data sources","Sharing a dashboard link with stakeholders","Installing the Power BI mobile app"],"correct":[1],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"The workflow begins by connecting to data sources and importing data into Power BI Desktop, which can then be modeled and visualized.","source":{"title":"Explore fundamentals of data visualization — Microsoft Learn","url":"https://learn.microsoft.com/en-us/training/modules/explore-fundamentals-data-visualization/"}},{"id":"gen-192","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A data analyst wants to examine whether there is a correlation between advertising spend and units sold across many stores. Which visualization best reveals the relationship between two numeric measures?","options":["A scatter chart","A single card","A slicer","A pie chart"],"correct":[0],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A scatter chart plots two numeric values on the X and Y axes, making it effective for revealing correlations and patterns between two measures.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-193","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"In the Power BI service, what is a dashboard best described as?","options":["A Windows desktop application used to model data","A single-page canvas that pins visuals (tiles), often from one or more reports, for at-a-glance monitoring","A file format used to store raw imported tables","A tool that only runs on mobile phones"],"correct":[1],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"In the Power BI service, a dashboard is a single-page collection of pinned visual tiles, often drawn from multiple reports, used for consolidated monitoring.","source":{"title":"What is Power BI? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/fundamentals/power-bi-overview"}},{"id":"gen-194","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"An analyst wants viewers to ask questions in natural language such as \"total sales by region last year\" and get a visual answer. Which Power BI capability supports this?","options":["Row-level security","Q&A (natural language query)","Incremental refresh","Data lineage view"],"correct":[1],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Power BI's Q&A feature lets users type natural-language questions and returns an appropriate visualization based on the underlying data model.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-195","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A report author wants to show how a total, such as annual budget, is divided among a small number of expense categories as parts of a whole. Which visualization is appropriate when there are only a few categories?","options":["A line chart","A gauge","A pie or donut chart","A scatter chart"],"correct":[2],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Pie and donut charts show proportion as parts of a whole and work best when there are only a few categories to compare.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-196","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"Which of the following best describes a semantic model (dataset) in Power BI?","options":["A collection of pinned tiles used for monitoring","The data model containing tables, relationships, and measures that reports use as their data source","A physical Azure storage account holding CSV files","A printed export of a report page"],"correct":[1],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A semantic model (dataset) is the underlying data model—tables, relationships, and measures—that one or more reports connect to and visualize.","source":{"title":"What is Power BI? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/fundamentals/power-bi-overview"}},{"id":"gen-197","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"A hospital wants to display hierarchical category data, such as departments and their sub-costs, using nested rectangles sized by value. Which visualization fits this need?","options":["A treemap","A KPI card","A line chart","A slicer"],"correct":[0],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"A treemap displays hierarchical data as nested rectangles whose sizes reflect their values, useful for showing proportions within categories.","source":{"title":"Visualizations in Power BI reports — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/visuals/power-bi-visualizations-overview"}},{"id":"gen-198","sourceBank":"microsoft-learn","type":"single","generated":true,"question":"After an analyst finishes authoring a report in Power BI Desktop, which action makes the report available to colleagues through the Power BI service?","options":["Exporting the report as a Word document","Saving the file to a local hard drive only","Publishing the report to a workspace in the Power BI service","Renaming the .pbix file"],"correct":[2],"skill":4,"sub":"4.3","confidence":"high","set":null,"section":null,"topic":null,"explanation":"Publishing the report from Power BI Desktop to a workspace in the Power BI service makes it available online for sharing and collaboration.","source":{"title":"What is Power BI? — Microsoft Learn","url":"https://learn.microsoft.com/en-us/power-bi/fundamentals/power-bi-overview"}}];
